import type { IAgentRepository } from "../../../domain/repositories/IAgentRepo.js";
import type {
  CreateAgentDTO,
  UpdateAgentDTO,
  AgentFilterDTO,
} from "../../../domain/dtos/AgentDTO.js";
import type { CursorPaginatedData } from "../../../types/response.js";
import type { AgentEntity } from "../../../domain/entities/Agent.js";
import { NotFoundError } from "../../../domain/errors/NotFoundError.js";

export class CreateAgentUseCase {
  constructor(private readonly repo: IAgentRepository) {}
  async execute(data: CreateAgentDTO): Promise {
    return await this.repo.create(data);
  }
}

export class UpdateAgentUseCase {
  constructor(private readonly repo: IAgentRepository) {}
  async execute(id: number, data: UpdateAgentDTO): Promise {
    return await this.repo.update(id, data);
  }
}

export class GetAgentByIdUseCase {
  constructor(private readonly repo: IAgentRepository) {}
  async execute(id: number): Promise {
    const result = await this.repo.findById(id);
    if (!result) throw new NotFoundError("Agent tidak ditemukan");
    return result;
  }
}

export class GetAgentsPaginatedUseCase {
  constructor(private readonly repo: IAgentRepository) {}
  async execute(
    limit: number,
    cursor?: number,
    filters?: AgentFilterDTO,
  ): Promise<CursorPaginatedData> {
    return await this.repo.findWithCursorPagination(limit, cursor, filters);
  }
}

export class DeleteAgentUseCase {
  constructor(private readonly repo: IAgentRepository) {}
  async execute(id: number): Promise {
    await this.repo.delete(id);
  }
}

import type { IAuditLogRepository } from "../../../domain/repositories/IAuditLogRepo.js";
import type { AuditLogFilterDTO } from "../../../domain/dtos/AuditLogDTO.js";

export class GetAuditLogsPaginatedUseCase {
  constructor(private readonly repo: IAuditLogRepository) {}

  async execute(limit: number, cursor?: number, filters?: AuditLogFilterDTO) {
    return await this.repo.findWithCursorPagination(limit, cursor, filters);
  }
}

import type { IUserRepository } from "../../../domain/repositories/IUserRepo.js";
import type { UserResponseDTO } from "../../../domain/dtos/UserDTO.js";
import { AppError } from "../../../domain/errors/AppError.js";
import { StatusCodes } from "http-status-codes";

export class GetProfileUseCase {
  constructor(private readonly userRepo: IUserRepository) {}

  async execute(userId: number): Promise {
    const user = await this.userRepo.findById(userId);
    if (!user) {
      throw new AppError(StatusCodes.NOT_FOUND, "User tidak ditemukan");
    }
    return {
      id: user.id,
      username: user.username,
      email: user.email,
      role: user.role,
      createdAt: user.createdAt,
    };
  }
}

import jwt from "jsonwebtoken";
import type { SignOptions } from "jsonwebtoken";
import type { IUserRepository } from "../../../domain/repositories/IUserRepo";
import { comparePassword } from "../../../utils/hashing";
import { AppError } from "../../../domain/errors/AppError";
import { env } from "../../../config/env";
import { StatusCodes } from "http-status-codes";
import type {
  JwtUserPayload,
  LoginResponseDTO,
  LoginUserDTO,
} from "../../../domain/dtos/UserDTO.js";

export class LoginUserUseCase {
  constructor(private readonly userRepo: IUserRepository) {}

  async execute(data: LoginUserDTO): Promise {
    const user = await this.userRepo.findByEmail(data.email);
    const invalidCredentialsError = new AppError(
      StatusCodes.UNAUTHORIZED,
      "Email atau Password salah",
    );

    if (!user?.password) {
      throw invalidCredentialsError;
    }

    const isPasswordValid = await comparePassword(data.password, user.password);

    if (!isPasswordValid) {
      throw invalidCredentialsError;
    }

    const payload: JwtUserPayload = {
      userId: user.id,
      username: user.username,
      email: user.email,
      role: user.role,
    };
    const jwtOptions: SignOptions = { expiresIn: "1h" };
    const token = jwt.sign(payload, env.JWT_SECRET, jwtOptions);

    return {
      token,
      user: {
        id: user.id,
        username: user.username,
        email: user.email,
        role: user.role,
      },
    };
  }
}

import type {
  RegisterUserDTO,
  UserResponseDTO,
} from "../../../domain/dtos/UserDTO";
import type { IUserRepository } from "../../../domain/repositories/IUserRepo";
import { hashPassword } from "../../../utils/hashing";
import { ConflictError } from "../../../domain/errors/ConflictError";
import { Role } from "@prisma/client";

export class RegisterUserUseCase {
  constructor(private readonly userRepo: IUserRepository) {}

  async execute(data: RegisterUserDTO): Promise {
    if (data.email) {
      const existingUser = await this.userRepo.findByEmail(data.email);
      if (existingUser) {
        throw new ConflictError("Email sudah terdaftar");
      }
    }

    const hashedPassword = await hashPassword(data.password!);
    const roleToAssign = data.role ?? Role.CUSTOMER;

    const newUser = await this.userRepo.create({
      ...data,
      password: hashedPassword,
      role: roleToAssign,
    });

    return {
      id: newUser.id,
      username: newUser.username,
      email: newUser.email,
      role: newUser.role,
      createdAt: newUser.createdAt,
    };
  }
}

