import { Prisma } from "@prisma/client";
import type { PrismaClient, Perumahan } from "@prisma/client";
import type { IPerumahanRepository } from "./IPerumahanRepo.js";
import type {
  CreatePerumahanDTO,
  UpdatePerumahanDTO,
  PerumahanFilterDTO,
} from "../dtos/PerumahanDTO.js";
import type { CursorPaginatedData } from "../../types/response.js";
import { NotFoundError } from "../errors/NotFoundError.js";
import { ConflictError } from "../errors/ConflictError.js";

export class PerumahanRepository implements IPerumahanRepository {
  constructor(private readonly db: PrismaClient) {}

  async create(data: CreatePerumahanDTO): Promise {
    try {
      return await this.db.perumahan.create({ data });
    } catch (error) {
      if (
        error instanceof Prisma.PrismaClientKnownRequestError &&
        error.code === "P2002"
      ) {
        throw new ConflictError(
          "Nama, Logo, atau Alamat Perumahan sudah terdaftar",
        );
      }
      throw error;
    }
  }

  async findById(id: number): Promise {
    return await this.db.perumahan.findUnique({ where: { id } });
  }

  async update(id: number, data: UpdatePerumahanDTO): Promise {
    const existing = await this.findById(id);
    if (!existing) throw new NotFoundError("Perumahan tidak ditemukan");

    try {
      const updateData: Prisma.PerumahanUncheckedUpdateInput = {};
      if (data.nama !== undefined) updateData.nama = data.nama;
      if (data.logo !== undefined) updateData.logo = data.logo;
      if (data.alamat !== undefined) updateData.alamat = data.alamat;

      return await this.db.perumahan.update({
        where: { id },
        data: updateData,
      });
    } catch (error) {
      if (
        error instanceof Prisma.PrismaClientKnownRequestError &&
        error.code === "P2002"
      ) {
        throw new ConflictError(
          "Nama, Logo, atau Alamat Perumahan sudah digunakan",
        );
      }
      throw error;
    }
  }

  async findWithCursorPagination(
    limit: number,
    cursor?: number,
    filters?: PerumahanFilterDTO,
  ): Promise<CursorPaginatedData> {
    const where: Prisma.PerumahanWhereInput = {};

    if (filters?.startDate || filters?.endDate) {
      where.createdAt = {};
      if (filters.startDate) where.createdAt.gte = new Date(filters.startDate);
      if (filters.endDate) where.createdAt.lte = new Date(filters.endDate);
    }

    if (filters?.search) {
      where.OR = [
        { nama: { contains: filters.search } },
        { alamat: { contains: filters.search } },
      ];
    }

    let orderByClause: Prisma.PerumahanOrderByWithRelationInput[] = [
      { createdAt: "desc" },
      { id: "asc" },
    ];

    if (filters?.orderBy) {
      const { field, direction } = filters.orderBy;
      const validFields = ["nama", "alamat", "createdAt"];
      if (validFields.includes(field)) {
        orderByClause = [{ [field]: direction }, { id: "asc" }];
      }
    }

    const items = await this.db.perumahan.findMany({
      take: limit + 1,
      ...(cursor && { skip: 1, cursor: { id: cursor } }),
      where,
      orderBy: orderByClause,
    });

    let hasNextPage = false;
    if (items.length > limit) {
      hasNextPage = true;
      items.pop();
    }

    const nextCursor = hasNextPage ? (items.at(-1)?.id ?? null) : null;

    return {
      items,
      meta: { nextCursor, hasNextPage },
    };
  }

  async delete(id: number): Promise {
    const existing = await this.findById(id);
    if (!existing) throw new NotFoundError("Perumahan tidak ditemukan");

    try {
      await this.db.perumahan.delete({ where: { id } });
    } catch (error) {
      if (
        error instanceof Prisma.PrismaClientKnownRequestError &&
        error.code === "P2003"
      ) {
        throw new ConflictError(
          "Perumahan tidak dapat dihapus karena sudah terhubung dengan data Kavling atau Rekening PT.",
        );
      }
      throw error;
    }
  }
}

import type { PrismaClient } from "@prisma/client";
import { Prisma } from "@prisma/client";
import type { IProgressPenjualanRepository } from "./IProgressPenjualanRepo.js";
import type {
  CreateProgressPenjualanDTO,
  UpdateProgressPenjualanDTO,
  ProgressPenjualanResponseDTO,
} from "../dtos/ProgressPenjualanDTO.js";
import { ProgressPenjualanMapper } from "../../infrastructure/mapper/ProgressPenjualanMapper.js";
import { NotFoundError } from "../errors/NotFoundError.js";
import { ConflictError } from "../errors/ConflictError.js";

export class ProgressPenjualanRepository implements IProgressPenjualanRepository {
  constructor(private readonly db: PrismaClient) {}

  async create(
    data: CreateProgressPenjualanDTO,
  ): Promise {
    const existing = await this.findByPenjualanId(data.penjualanId);
    if (existing) {
      throw new ConflictError(
        "Progress Penjualan untuk transaksi ini sudah ada.",
      );
    }

    const result = await this.db.progressPenjualan.create({
      data: { penjualanId: data.penjualanId },
    });

    return ProgressPenjualanMapper.toDomain(result);
  }

  async findByPenjualanId(
    penjualanId: number,
  ): Promise {
    const result = await this.db.progressPenjualan.findUnique({
      where: { penjualanId },
    });
    if (!result) return null;
    return ProgressPenjualanMapper.toDomain(result);
  }

  async update(
    penjualanId: number,
    data: UpdateProgressPenjualanDTO,
  ): Promise {
    const existing = await this.findByPenjualanId(penjualanId);
    if (!existing) {
      throw new NotFoundError("Progress Penjualan tidak ditemukan.");
    }

    const updateData: Prisma.ProgressPenjualanUpdateInput = {};

    if (data.berkasCustomerValid !== undefined)
      updateData.berkasCustomerValid = data.berkasCustomerValid;
    if (data.fileSp3k !== undefined) updateData.fileSp3k = data.fileSp3k;
    if (data.fileSalinanAjb !== undefined)
      updateData.fileSalinanAjb = data.fileSalinanAjb;
    if (data.filePpjb !== undefined) updateData.filePpjb = data.filePpjb;

    if (data.nilaiAjb !== undefined) {
      updateData.nilaiAjb = data.nilaiAjb ?? null;

      if (data.nilaiAjb) {
        updateData.biayaPph = data.nilaiAjb * 0.025;

        const dppBphtb = Math.max(0, data.nilaiAjb - 80000000);
        updateData.biayaBphtb = dppBphtb * 0.05;
      } else {
        updateData.biayaBphtb = null;
        updateData.biayaPph = null;
      }
    }

    if (data.fileAjb !== undefined) updateData.fileAjb = data.fileAjb;
    if (data.fileBast !== undefined) updateData.fileBast = data.fileBast;
    if (data.checklistBast !== undefined) {
      updateData.checklistBast =
        data.checklistBast === null
          ? Prisma.DbNull
          : (data.checklistBast as Prisma.InputJsonValue);
    }

    const result = await this.db.progressPenjualan.update({
      where: { penjualanId },
      data: updateData,
    });

    return ProgressPenjualanMapper.toDomain(result);
  }
}

import { Prisma } from "@prisma/client";
import type { PrismaClient } from "@prisma/client";
import type { IUserRepository } from "./IUserRepo";
import type { UserEntity } from "../entities/User";
import type {
  RegisterUserDTO,
  UpdateUserDTO,
  UserFilterDTO,
} from "../dtos/UserDTO";
import { UserMapper } from "../../infrastructure/mapper/UserMapper";
import { ConflictError } from "../errors/ConflictError";
import { NotFoundError } from "../errors/NotFoundError.js";
import type { CursorPaginatedData } from "../../types/response.js";

export class UserRepository implements IUserRepository {
  constructor(private readonly db: PrismaClient) {}
  async findWithCursorPagination(
    limit: number,
    cursor?: number,
    filters?: UserFilterDTO,
  ): Promise<CursorPaginatedData> {
    const where: Prisma.UserWhereInput = {};

    if (filters?.startDate || filters?.endDate) {
      where.createdAt = {};
      if (filters.startDate) where.createdAt.gte = new Date(filters.startDate);
      if (filters.endDate) where.createdAt.lte = new Date(filters.endDate);
    }

    if (filters?.search) {
      where.OR = [
        { username: { contains: filters.search } },
        { email: { contains: filters.search } },
      ];
    }
    if (filters?.role) {
      where.role = filters.role;
    }

    let orderByClause: Prisma.UserOrderByWithRelationInput[] = [
      { createdAt: "desc" },
      { id: "asc" },
    ];

    if (filters?.orderBy) {
      const { field, direction } = filters.orderBy;
      const validFields = ["username", "email", "role", "createdAt"];
      if (validFields.includes(field)) {
        orderByClause = [{ [field]: direction }, { id: "asc" }];
      }
    }

    const items = await this.db.user.findMany({
      take: limit + 1,
      ...(cursor && { skip: 1, cursor: { id: cursor } }),
      where,
      orderBy: orderByClause,
    });

    let hasNextPage = false;
    if (items.length > limit) {
      hasNextPage = true;
      items.pop();
    }

    const nextCursor = hasNextPage ? (items.at(-1)?.id ?? null) : null;

    return {
      items: items.map((item) => UserMapper.toDomain(item)),
      meta: { nextCursor, hasNextPage },
    };
  }

  async create(data: RegisterUserDTO): Promise {
    try {
      const result = await this.db.user.create({
        data: {
          username: data.username,
          email: data.email,
          password: data.password ?? "",
          role: data.role,
        },
      });
      return UserMapper.toDomain(result);
    } catch (error) {
      if (
        error instanceof Prisma.PrismaClientKnownRequestError &&
        error.code === "P2002"
      ) {
        throw new ConflictError("Email sudah terdaftar");
      }
      throw error;
    }
  }

  async update(id: number, data: UpdateUserDTO): Promise {
    try {
      const existing = await this.db.user.findUnique({ where: { id } });
      if (!existing) throw new NotFoundError("User tidak ditemukan");

      const updateData: Prisma.UserUpdateInput = {};

      if (data.username !== undefined) updateData.username = data.username;
      if (data.email !== undefined) updateData.email = data.email;
      if (data.password !== undefined) updateData.password = data.password;
      if (data.role !== undefined) updateData.role = data.role;

      const result = await this.db.user.update({
        where: { id },
        data: updateData,
      });

      return UserMapper.toDomain(result);
    } catch (error) {
      if (
        error instanceof Prisma.PrismaClientKnownRequestError &&
        error.code === "P2002"
      ) {
        throw new ConflictError("Email sudah digunakan user lain.");
      }
      throw error;
    }
  }

  async findByEmail(email: string): Promise {
    const result = await this.db.user.findUnique({ where: { email } });
    if (!result) return null;
    return UserMapper.toDomain(result);
  }

  async findById(id: number): Promise {
    const result = await this.db.user.findUnique({ where: { id } });
    if (!result) return null;
    return UserMapper.toDomain(result);
  }

  async findAll(): Promise {
    const results = await this.db.user.findMany({
      orderBy: { createdAt: "desc" },
    });
    return results.map((u) => UserMapper.toDomain(u));
  }
}

