import type { Request, Response, NextFunction } from "express";
import jwt from "jsonwebtoken";
import { StatusCodes } from "http-status-codes";
import { env } from "../config/env";
import { sendResponse } from "../utils/response";
import type { JwtUserPayload } from "../domain/dtos/UserDTO";

export const authenticate = (
  req: Request,
  res: Response,
  next: NextFunction,
): void => {
  const authHeader = req.headers.authorization;

  if (!authHeader?.startsWith("Bearer ")) {
    sendResponse(
      res,
      StatusCodes.UNAUTHORIZED,
      "Access denied. No token provided.",
    );
    return;
  }

  const token = authHeader.split(" ").pop()?.trim();

  if (!token) {
    sendResponse(
      res,
      StatusCodes.UNAUTHORIZED,
      "Access denied. Invalid token format.",
    );
    return;
  }

  try {
    const decoded = jwt.verify(token, env.JWT_SECRET) as JwtUserPayload;
    req.user = decoded;
    next();
  } catch (error) {
    let message = "Invalid token.";
    if (error instanceof jwt.TokenExpiredError) {
      message = "Token expired.";
    }
    sendResponse(res, StatusCodes.UNAUTHORIZED, message);
  }
};

export const requireRole = (allowedRoles: string[]) => {
  return (req: Request, res: Response, next: NextFunction): void => {
    if (!req.user) {
      sendResponse(res, StatusCodes.UNAUTHORIZED, "User not authenticated");
      return;
    }

    if (!allowedRoles.includes(req.user.role)) {
      sendResponse(
        res,
        StatusCodes.FORBIDDEN,
        "You do not have permission to access this resource",
      );
      return;
    }

    next();
  };
};

import type { Request, Response, NextFunction } from "express";
import { sendResponse } from "../utils/response";
import { env } from "../config/env";
import { StatusCodes } from "http-status-codes";
import { ZodError } from "zod";
import { AppError } from "../domain/errors/AppError.js";
import * as Sentry from "@sentry/node";

export const notFoundHandler = (req: Request, res: Response): void => {
  sendResponse(
    res,
    StatusCodes.NOT_FOUND,
    `Endpoint ${req.originalUrl} not found`,
  );
};

export const globalErrorHandler = (
  err: Error,
  req: Request,
  res: Response,
  _next: NextFunction,
): void => {
  req.log?.error(err);

  const isProd = env.NODE_ENV === "production";
  let statusCode = StatusCodes.INTERNAL_SERVER_ERROR;
  let message = "Internal Server Error";
  let errorsDetail: unknown = undefined;

  if (
    err instanceof SyntaxError &&
    "status" in err &&
    err.status === 400 &&
    "body" in err
  ) {
    statusCode = StatusCodes.BAD_REQUEST;
    message = "Invalid JSON payload passed";
    errorsDetail = { detail: err.message };
  } else if (err instanceof ZodError) {
    statusCode = StatusCodes.BAD_REQUEST;
    message = "Validation Error";
    errorsDetail = err.issues.map((e) => ({
      field: e.path.join("."),
      message: e.message,
    }));
  } else if (err instanceof AppError) {
    statusCode = err.statusCode;
    message = err.message;
  }

  if (statusCode === StatusCodes.INTERNAL_SERVER_ERROR) {
    Sentry.captureException(err);
  }

  const shouldShowStack =
    !isProd && statusCode === StatusCodes.INTERNAL_SERVER_ERROR;

  sendResponse(
    res,
    statusCode,
    message,
    null,
    errorsDetail ??
      (shouldShowStack
        ? { message: err.message, stack: err.stack }
        : undefined),
  );
};

import type { Request, Response, NextFunction } from "express";
import type { z } from "zod";

interface ValidationSchemas {
  body?: z.ZodTypeAny;
  query?: z.ZodTypeAny;
  params?: z.ZodTypeAny;
}

export const validate = (schemas: ValidationSchemas) => {
  return (req: Request, res: Response, next: NextFunction): void => {
    try {
      if (schemas.body) {
        req.body = schemas.body.parse(req.body);
      }

      if (schemas.params) {
        const validatedParams = schemas.params.parse(req.params);
        Object.keys(req.params).forEach((key) => delete req.params[key]);
        Object.assign(req.params, validatedParams);
      }

      if (schemas.query) {
        const validatedQuery = schemas.query.parse(req.query);

        Object.keys(req.query).forEach((key) => delete req.query[key]);

        Object.assign(req.query, validatedQuery);
      }

      next();
    } catch (error: unknown) {
      next(error);
    }
  };
};

import type { Request, Response } from "express";
import { StatusCodes } from "http-status-codes";
import { sendResponse } from "../../utils/response.js";
import type { TypedRequest } from "../../types/request.js";

import type {
  CreateAgentUseCase,
  UpdateAgentUseCase,
  GetAgentByIdUseCase,
  GetAgentsPaginatedUseCase,
  DeleteAgentUseCase,
} from "../../application/usecases/agent/AgentUseCases.js";

import type {
  createAgentSchema,
  updateAgentSchema,
} from "../../validations/agentSchema.js";
import { getAgentsPaginatedSchema } from "../../validations/agentSchema.js";
import type { AgentFilterDTO } from "../../domain/dtos/AgentDTO.js";

export class AgentController {
  constructor(
    private readonly createUseCase: CreateAgentUseCase,
    private readonly updateUseCase: UpdateAgentUseCase,
    private readonly getByIdUseCase: GetAgentByIdUseCase,
    private readonly getPaginatedUseCase: GetAgentsPaginatedUseCase,
    private readonly deleteUseCase: DeleteAgentUseCase,
  ) {}

  create = async (
    req: TypedRequest,
    res: Response,
  ): Promise => {
    const result = await this.createUseCase.execute(req.body);
    sendResponse(
      res,
      StatusCodes.CREATED,
      "Agent berhasil ditambahkan",
      result,
    );
  };

  update = async (
    req: TypedRequest<
      typeof updateAgentSchema.body,
      any,
      typeof updateAgentSchema.params
    >,
    res: Response,
  ): Promise => {
    const id = parseInt(req.params.id, 10);
    const result = await this.updateUseCase.execute(id, req.body);
    sendResponse(res, StatusCodes.OK, "Agent berhasil diperbarui", result);
  };

  getById = async (
    req: TypedRequest,
    res: Response,
  ): Promise => {
    const id = parseInt(req.params.id, 10);
    const result = await this.getByIdUseCase.execute(id);
    sendResponse(res, StatusCodes.OK, "Data agent berhasil diambil", result);
  };

  getPaginated = async (req: Request, res: Response): Promise => {
    const { limit, cursor, ...filters } = getAgentsPaginatedSchema.query.parse(
      req.query,
    );
    const parsedCursor = cursor ? Number(cursor) : undefined;

    const result = await this.getPaginatedUseCase.execute(
      limit,
      parsedCursor,
      filters as AgentFilterDTO,
    );

    sendResponse(res, StatusCodes.OK, "Daftar agent berhasil diambil", result);
  };

  delete = async (
    req: TypedRequest,
    res: Response,
  ): Promise => {
    const id = parseInt(req.params.id, 10);
    await this.deleteUseCase.execute(id);
    sendResponse(res, StatusCodes.OK, "Agent berhasil dihapus");
  };
}

