import app from "./app";
import { env } from "./config/env";
import { prisma } from "./infrastructure/database/prisma";
import { logger } from "./utils/logger";
const PORT = env.PORT;
const server = app.listen(PORT, () => {
  console.log(`🚀 Server is running on http://localhost:${PORT}`);
});
const shutdown = (signal: string) => {
  console.log(`\n${signal} received. Closing resources...`);
  server.close(async () => {
    await prisma.$disconnect();
    console.log("HTTP server and Database connection closed.");
    process.exit(0);
  });
};
process.on("uncaughtException", (err) => {
  logger.fatal(err, "Uncaught Exception terdeteksi. Mematikan server...");
  process.exit(1);
});

process.on("unhandledRejection", async (reason) => {
  logger.fatal({ reason }, "Unhandled Rejection");
  await prisma.$disconnect();
  server.close(() => process.exit(1));
});
process.on("SIGUSR2", () => shutdown("SIGUSR2"));
process.on("SIGTERM", () => shutdown("SIGTERM"));
process.on("SIGINT", () => shutdown("SIGINT"));

import { PrismaClient, Role } from "@prisma/client";
import { faker } from "@faker-js/faker/locale/id_ID";
import bcrypt from "bcrypt";

const prisma = new PrismaClient();

export const UserFactory = {
  async create(
    overrides: Partial<Parameters[0]["data"]> = {},
  ) {
    const defaultPassword = await bcrypt.hash("password123", 10);
    return await prisma.user.create({
      data: {
        username: faker.internet.displayName(),
        email: faker.internet.email(),
        password: defaultPassword,
        role: Role.CUSTOMER,
        ...overrides,
      },
    });
  },
};

import { prisma } from "../infrastructure/database/prisma";

export const prismaTest = prisma;

export const clearDatabase = async () => {
  const tableNames = await prismaTest.$queryRaw<
    { TABLE_NAME: string }[]
  >`SELECT TABLE_NAME from information_schema.TABLES WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME != '_prisma_migrations';`;

  for (const { TABLE_NAME } of tableNames) {
    if (TABLE_NAME !== "_prisma_migrations") {
      try {
        await prismaTest.$executeRawUnsafe(`SET FOREIGN_KEY_CHECKS = 0;`);
        await prismaTest.$executeRawUnsafe(`TRUNCATE TABLE \`${TABLE_NAME}\`;`);
        await prismaTest.$executeRawUnsafe(`SET FOREIGN_KEY_CHECKS = 1;`);
      } catch (error) {
        console.log({ error });
      }
    }
  }
};

export const disconnectDatabase = async () => {
  await prismaTest.$disconnect();
};

