import { Prisma } from "@prisma/client";
import type { PrismaClient } from "@prisma/client";
import type { INotarisRepository } from "./INotarisRepo.js";
import type { NotarisEntity } from "../entities/Notaris.js";
import type {
  CreateNotarisDTO,
  UpdateNotarisDTO,
  NotarisFilterDTO,
} from "../dtos/NotarisDTO.js";
import type { CursorPaginatedData } from "../../types/response.js";
import { NotFoundError } from "../errors/NotFoundError.js";
import { NotarisMapper } from "../../infrastructure/mapper/NotarisMapper.js";
import { ConflictError } from "../errors/ConflictError.js";

// Reusable include object agar query seragam
const notarisIncludeRelations = {
  pics: true,
  detailKavlingPajak: {
    include: {
      penjualan: {
        include: {
          customer: { select: { nama: true } },
          kavling: {
            include: { perumahan: { select: { nama: true } } },
          },
        },
      },
    },
  },
} satisfies Prisma.NotarisInclude;

export class NotarisRepository implements INotarisRepository {
  constructor(private readonly db: PrismaClient) {}

  async create(data: CreateNotarisDTO): Promise {
    const createData: Prisma.NotarisCreateInput = {
      nama: data.nama,
      biayaAjb: data.biayaAjb,
    };

    if (data.pics && data.pics.length > 0) {
      createData.pics = {
        create: data.pics.map((p) => ({
          nama: p.nama,
          noHp: p.noHp,
          alamat: p.alamat ?? null,
        })),
      };
    }

    const result = await this.db.notaris.create({
      data: createData,
      include: notarisIncludeRelations,
    });

    return NotarisMapper.toDomain(result);
  }

  async findById(id: number): Promise {
    const result = await this.db.notaris.findUnique({
      where: { id },
      include: notarisIncludeRelations,
    });
    if (!result) return null;
    return NotarisMapper.toDomain(result);
  }

  async update(id: number, data: UpdateNotarisDTO): Promise {
    const existing = await this.findById(id);
    if (!existing) throw new NotFoundError("Notaris tidak ditemukan");

    const updateData: Prisma.NotarisUpdateInput = {};

    if (data.nama !== undefined) updateData.nama = data.nama;
    if (data.biayaAjb !== undefined) updateData.biayaAjb = data.biayaAjb;

    if (data.pics) {
      updateData.pics = {
        deleteMany: {},
        create: data.pics.map((p) => ({
          nama: p.nama,
          noHp: p.noHp,
          alamat: p.alamat ?? null,
        })),
      };
    }

    const result = await this.db.notaris.update({
      where: { id },
      data: updateData,
      include: notarisIncludeRelations,
    });

    return NotarisMapper.toDomain(result);
  }

  async findWithCursorPagination(
    limit: number,
    cursor?: number,
    filters?: NotarisFilterDTO,
  ): Promise<CursorPaginatedData> {
    const where: Prisma.NotarisWhereInput = {};

    if (filters?.search) {
      where.nama = { contains: filters.search };
    }

    const items = await this.db.notaris.findMany({
      take: limit + 1,
      ...(cursor && { skip: 1, cursor: { id: cursor } }),
      where,
      orderBy: [{ id: "desc" }],
      include: notarisIncludeRelations,
    });

    let hasNextPage = false;
    if (items.length > limit) {
      hasNextPage = true;
      items.pop();
    }

    return {
      items: items.map((item) => NotarisMapper.toDomain(item)),
      meta: {
        nextCursor: hasNextPage ? (items.at(-1)?.id ?? null) : null,
        hasNextPage,
      },
    };
  }

  async delete(id: number): Promise {
    const existing = await this.findById(id);
    if (!existing) throw new NotFoundError("Notaris tidak ditemukan");

    try {
      await this.db.notaris.delete({ where: { id } });
    } catch (error) {
      if (
        error instanceof Prisma.PrismaClientKnownRequestError &&
        error.code === "P2003"
      ) {
        throw new ConflictError(
          "Notaris tidak dapat dihapus karena sudah digunakan di transaksi/AJB.",
        );
      }
      throw error;
    }
  }
}

import {
  GoogleGenerativeAI,
  SchemaType,
  type Schema,
} from "@google/generative-ai";
import { AppError } from "../../domain/errors/AppError.js";
import { StatusCodes } from "http-status-codes";
import { writeFileSync } from "fs";

export class GoogleVisionService {
  private genAI: GoogleGenerativeAI;

  constructor() {
    const apiKey = process.env.GEMINI_API_KEY;
    if (!apiKey) {
      console.warn("Peringatan: GEMINI_API_KEY belum diset di file .env");
    }
    this.genAI = new GoogleGenerativeAI(apiKey ?? "");
  }

  async extractKtpData(imageBuffer: Buffer): Promise<{
    nik: string | null;
    nama: string | null;
    alamat: string | null;
  }> {
    try {
      const ktpSchema: Schema = {
        type: SchemaType.OBJECT,
        properties: {
          nik: {
            type: SchemaType.STRING,
            description: "16 digit angka NIK. Perbaiki typo umum OCR.",
          },
          nama: {
            type: SchemaType.STRING,
            description: "Nama lengkap tanpa kata 'Nama' atau 'Name'.",
          },
          alamat: {
            type: SchemaType.STRING,
            description:
              "Gabungan Alamat, RT/RW, Kel/Desa, dan Kecamatan menjadi satu string lengkap dan rapi.",
          },
        },
        required: ["nik", "nama", "alamat"],
      };

      const model = this.genAI.getGenerativeModel({
        model: "gemini-2.5-flash",
        generationConfig: {
          responseMimeType: "application/json",
          responseSchema: ktpSchema,
          temperature: 0.0,
        },
      });

      const imagePart = {
        inlineData: {
          data: imageBuffer.toString("base64"),
          mimeType: "image/jpeg",
        },
      };

      const prompt = `
    Anda adalah sistem ekstraksi OCR khusus KTP Indonesia yang berpresisi tinggi.
    Tugas Anda mengekstrak informasi dari gambar KTP terlampir ke format JSON.

    ATURAN SANGAT KETAT (DILARANG MELANGGAR):
    1. ANTI-HALUSINASI: BACA HANYA teks yang benar-benar tertulis di gambar. DILARANG KERAS mengarang, memanipulasi, atau menebak nama/data.
    2. JIKA BURAM: Jika bagian NIK atau Nama buram, tertutup jari, terkena pantulan cahaya, atau tidak terbaca dengan yakin 100%, Anda WAJIB mereturn null. Jangan pernah menebak.
    3. NIK harus tepat 16 digit. Jika ada karakter mirip angka (O jadi 0, l/I jadi 1), perbaiki.
    4. NAMA: Ambil nama persis seperti yang tertulis.
  `;

      writeFileSync("debug_ktp.jpg", imageBuffer);
      console.log(
        "Gambar KTP untuk debug telah disimpan sebagai debug_ktp.jpg",
      );

      const result = await model.generateContent([prompt, imagePart]);
      const responseText = result.response.text();

      interface ExpectedKtpJson {
        nik?: string | null;
        nama?: string | null;
        alamat?: string | null;
      }

      const parsedData = JSON.parse(responseText) as ExpectedKtpJson;

      return {
        nik: parsedData.nik ?? null,
        nama: parsedData.nama ?? null,
        alamat: parsedData.alamat ?? null,
      };
    } catch (error) {
      console.error("Gemini Multimodal Extraction Error:", error);
      throw new AppError(
        StatusCodes.INTERNAL_SERVER_ERROR,
        "Gagal memproses gambar KTP.",
      );
    }
  }
}

import type { Prisma } from "@prisma/client";
import type { AgentEntity } from "../../domain/entities/Agent.js";

export type AgentWithRelations = Prisma.AgentGetPayload<{
  include: {
    pics: true;
    penjualan: {
      select: {
        id: true;
        noTransaksi: true;
        tanggal: true;
        hargaJual: true;
        status: true;
        customer: { select: { nama: true } };
        kavling: {
          select: {
            blok: true;
            nomorUnit: true;
            perumahan: { select: { nama: true } };
          };
        };
      };
    };
  };
}>;

export class AgentMapper {
  static toDomain(prismaAgent: AgentWithRelations): AgentEntity {
    return {
      id: prismaAgent.id,
      nik: prismaAgent.nik,
      kodeSales: prismaAgent.kodeSales,
      nama: prismaAgent.nama,
      alamat: prismaAgent.alamat,
      noHp: prismaAgent.noHp,
      email: prismaAgent.email,
      status: prismaAgent.status,
      createdAt: prismaAgent.createdAt,
      updatedAt: prismaAgent.updatedAt,
      pics: prismaAgent.pics.map((pic) => ({
        id: pic.id,
        agentId: pic.agentId,
        nama: pic.nama,
        noHp: pic.noHp,
        alamat: pic.alamat,
        createdAt: pic.createdAt,
        updatedAt: pic.updatedAt,
      })),

      penjualan: prismaAgent.penjualan
        ? prismaAgent.penjualan
            .filter((p) => p.status !== "BATAL")
            .map((p) => ({
              id: p.id,
              noTransaksi: p.noTransaksi,
              tanggal: p.tanggal,
              hargaJual: Number(p.hargaJual),
              status: p.status,
              customer: p.customer ? { nama: p.customer.nama } : null,
              kavling: p.kavling
                ? {
                    blok: p.kavling.blok,
                    nomorUnit: p.kavling.nomorUnit,
                    perumahan: p.kavling.perumahan
                      ? { nama: p.kavling.perumahan.nama }
                      : null,
                  }
                : null,
            }))
        : [],
    };
  }
}

import multer from "multer";
import { AppError } from "../domain/errors/AppError";
import { StatusCodes } from "http-status-codes";

const storage = multer.memoryStorage();
export const upload = multer({
  storage: storage,
  limits: {
    fileSize: 5 * 1024 * 1024,
  },
  fileFilter: (_req, file, cb) => {
    if (
      file.mimetype.startsWith("image/") ||
      file.mimetype === "application/pdf"
    ) {
      cb(null, true);
    } else {
      cb(
        new AppError(
          StatusCodes.BAD_REQUEST,
          "Hanya file gambar dan PDF yang diperbolehkan!",
          true,
        ),
      );
    }
  },
});

import type { Request, Response } from "express";
import { StatusCodes } from "http-status-codes";
import { sendResponse } from "../../utils/response.js";
import type { TypedRequest } from "../../types/request.js";

import type { CreateCustomerUseCase } from "../../application/usecases/customer/CreateCustomerUseCase.js";
import type { GetCustomerByIdUseCase } from "../../application/usecases/customer/GetCustomerByIdUseCase.js";
import type { GetCustomersPaginatedUseCase } from "../../application/usecases/customer/GetCustomersPaginatedUseCase.js";
import type { DeleteCustomerUseCase } from "../../application/usecases/customer/DeleteCustomerUseCase.js";
import type { UpdateCustomerUseCase } from "../../application/usecases/customer/UpdateCustomerUseCase.js";
import type { UploadCustomerDocumentUseCase } from "../../application/usecases/customer/UploadCustomerDocumentUseCase.js";
import type { GenerateCustomerAccountUseCase } from "../../application/usecases/customer/GenerateCustomerAccountUseCase.js";
import type { generateAccountSchema } from "../../validations/customerSchema.js";
import type {
  createCustomerSchema,
  updateCustomerSchema,
} from "../../validations/customerSchema.js";
import { getCustomersPaginatedSchema } from "../../validations/customerSchema.js";
import type { CustomerFilterDTO } from "../../domain/dtos/CustomerDTO.js";
import type { ExportCustomersUseCase } from "../../application/usecases/customer/ExportCustomersUseCase.js";
import type { ExportCustomersPdfUseCase } from "../../application/usecases/customer/ExportCustomersPdfUseCase.js";

export class CustomerController {
  constructor(
    private readonly createCustomerUseCase: CreateCustomerUseCase,
    private readonly updateCustomerUseCase: UpdateCustomerUseCase,
    private readonly getCustomerByIdUseCase: GetCustomerByIdUseCase,
    private readonly getCustomersPaginatedUseCase: GetCustomersPaginatedUseCase,
    private readonly deleteCustomerUseCase: DeleteCustomerUseCase,
    private readonly uploadDocumentUseCase: UploadCustomerDocumentUseCase,
    private readonly generateAccountUseCase: GenerateCustomerAccountUseCase,
    private readonly exportCustomersUseCase: ExportCustomersUseCase,
    private readonly exportCustomersPdfUseCase: ExportCustomersPdfUseCase,
  ) {}

  create = async (
    req: TypedRequest,
    res: Response,
  ): Promise => {
    const result = await this.createCustomerUseCase.execute(req.body);
    sendResponse(
      res,
      StatusCodes.CREATED,
      "Customer berhasil ditambahkan",
      result,
    );
  };

  update = async (
    req: TypedRequest<
      typeof updateCustomerSchema.body,
      any,
      typeof updateCustomerSchema.params
    >,
    res: Response,
  ): Promise => {
    const id = parseInt(req.params.id, 10);
    const result = await this.updateCustomerUseCase.execute(id, req.body);
    sendResponse(res, StatusCodes.OK, "Customer berhasil diperbarui", result);
  };

  getById = async (
    req: TypedRequest,
    res: Response,
  ): Promise => {
    const id = parseInt(req.params.id, 10);
    const result = await this.getCustomerByIdUseCase.execute(id);
    sendResponse(res, StatusCodes.OK, "Data customer berhasil diambil", result);
  };

  getPaginated = async (req: Request, res: Response): Promise => {
    const { limit, cursor, ...filters } =
      getCustomersPaginatedSchema.query.parse(req.query);
    const parsedCursor = cursor ? Number(cursor) : undefined;

    const result = await this.getCustomersPaginatedUseCase.execute(
      limit,
      parsedCursor,
      filters as CustomerFilterDTO,
    );
    sendResponse(
      res,
      StatusCodes.OK,
      "Daftar customer berhasil diambil",
      result,
    );
  };

  delete = async (
    req: TypedRequest,
    res: Response,
  ): Promise => {
    const id = parseInt(req.params.id, 10);
    await this.deleteCustomerUseCase.execute(id);
    sendResponse(res, StatusCodes.OK, "Customer berhasil dihapus");
  };

  uploadDocument = async (req: Request, res: Response): Promise => {
    const id = parseInt(req.params.id as string, 10);
    const docType = req.params.docType as string;
    const { namaDokumen } = req.body;

    if (isNaN(id)) {
      sendResponse(res, StatusCodes.BAD_REQUEST, "ID tidak valid");
      return;
    }

    if (!["fileKtp", "fileKk", "fileNpwp", "lainnya"].includes(docType)) {
      sendResponse(
        res,
        StatusCodes.BAD_REQUEST,
        "Parameter docType tidak valid",
      );
      return;
    }

    if (!req.file?.buffer) {
      sendResponse(res, StatusCodes.BAD_REQUEST, "File dokumen wajib diunggah");
      return;
    }

    const result = await this.uploadDocumentUseCase.execute(
      id,
      req.file.buffer,
      docType as "fileKtp" | "fileKk" | "fileNpwp" | "lainnya",
      namaDokumen,
    );

    sendResponse(res, StatusCodes.OK, "Dokumen berhasil diunggah", result);
  };
  generateAccount = async (
    req: TypedRequest<
      typeof generateAccountSchema.body,
      any,
      typeof generateAccountSchema.params
    >,
    res: Response,
  ): Promise => {
    const id = parseInt(req.params.id, 10);
    const { password } = req.body;

    const result = await this.generateAccountUseCase.execute(id, password);

    sendResponse(
      res,
      StatusCodes.CREATED,
      "Akun portal customer berhasil di-generate",
      result,
    );
  };
  exportExcel = async (_req: Request, res: Response): Promise => {
    const excelBuffer = await this.exportCustomersUseCase.execute();
    const timestamp = new Date().toISOString().slice(0, 10);
    const filename = `Data_Customer_${timestamp}.xlsx`;

    res.setHeader(
      "Content-Type",
      "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    );
    res.setHeader("Content-Disposition", `attachment; filename=${filename}`);
    res.status(StatusCodes.OK).send(excelBuffer);
  };

  exportPdf = async (_req: Request, res: Response): Promise => {
    const pdfBuffer = await this.exportCustomersPdfUseCase.execute();
    const timestamp = new Date().toISOString().slice(0, 10);
    const filename = `Data_Customer_${timestamp}.pdf`;

    res.setHeader("Content-Type", "application/pdf");
    res.setHeader("Content-Disposition", `attachment; filename=${filename}`);
    res.status(StatusCodes.OK).send(pdfBuffer);
  };
}

import type { Request, Response } from "express";
import { StatusCodes } from "http-status-codes";
import { sendResponse } from "../../utils/response.js";
import type { TypedRequest } from "../../types/request.js";

