import type { Prisma } from "@prisma/client";
import type { PrismaClient } from "@prisma/client";
import type { IAgentRepository } from "./IAgentRepo.js";
import type { AgentEntity } from "../entities/Agent.js";
import type {
  CreateAgentDTO,
  UpdateAgentDTO,
  AgentFilterDTO,
} from "../dtos/AgentDTO.js";
import type { CursorPaginatedData } from "../../types/response.js";
import { NotFoundError } from "../errors/NotFoundError.js";
import { ConflictError } from "../errors/ConflictError.js";
import { AgentMapper } from "../../infrastructure/mapper/AgentMapper.js";

export class AgentRepository implements IAgentRepository {
  constructor(private readonly db: PrismaClient) {}

  async create(data: CreateAgentDTO): Promise {
    const checkDuplicate = await this.db.agent.findFirst({
      where: { nik: data.nik },
    });

    if (checkDuplicate) {
      throw new ConflictError("NIK Agent sudah terdaftar");
    }

    const createData: Prisma.AgentCreateInput = {
      nik: data.nik,
      nama: data.nama,
      noHp: data.noHp,
      email: data.email ?? null,
      alamat: data.alamat ?? null,
    };

    if (data.status) {
      createData.status = data.status;
    }

    if (data.pics && data.pics.length > 0) {
      createData.pics = {
        create: data.pics.map((p) => ({
          nama: p.nama,
          noHp: p.noHp,
          alamat: p.alamat ?? null,
        })),
      };
    }

    const result = await this.db.agent.create({
      data: createData,
      include: {
        pics: true,
        penjualan: {
          orderBy: { createdAt: "desc" },
          select: {
            id: true,
            noTransaksi: true,
            tanggal: true,
            hargaJual: true,
            status: true,
            customer: { select: { nama: true } },
            kavling: {
              select: {
                blok: true,
                nomorUnit: true,
                perumahan: { select: { nama: true } },
              },
            },
          },
        },
      },
    });

    return AgentMapper.toDomain(result);
  }

  async findById(id: number): Promise {
    const result = await this.db.agent.findUnique({
      where: { id },
      include: {
        pics: true,
        penjualan: {
          orderBy: { createdAt: "desc" },
          select: {
            id: true,
            noTransaksi: true,
            tanggal: true,
            hargaJual: true,
            status: true,
            customer: { select: { nama: true } },
            kavling: {
              select: {
                blok: true,
                nomorUnit: true,
                perumahan: { select: { nama: true } },
              },
            },
          },
        },
      },
    });
    if (!result) return null;
    return AgentMapper.toDomain(result);
  }

  async update(id: number, data: UpdateAgentDTO): Promise {
    const existing = await this.findById(id);
    if (!existing) {
      throw new NotFoundError("Agent tidak ditemukan");
    }

    const updateData: Prisma.AgentUpdateInput = {};

    if (data.nik !== undefined) updateData.nik = data.nik;
    if (data.nama !== undefined) updateData.nama = data.nama;
    if (data.noHp !== undefined) updateData.noHp = data.noHp;
    if (data.email !== undefined) updateData.email = data.email ?? null;
    if (data.alamat !== undefined) updateData.alamat = data.alamat ?? null;
    if (data.status !== undefined) updateData.status = data.status;

    if (data.pics) {
      updateData.pics = {
        deleteMany: {},
        create: data.pics.map((p) => ({
          nama: p.nama,
          noHp: p.noHp,
          alamat: p.alamat ?? null,
        })),
      };
    }

    const result = await this.db.agent.update({
      where: { id },
      data: updateData,
      include: {
        pics: true,
        penjualan: {
          orderBy: { createdAt: "desc" },
          select: {
            id: true,
            noTransaksi: true,
            tanggal: true,
            hargaJual: true,
            status: true,
            customer: { select: { nama: true } },
            kavling: {
              select: {
                blok: true,
                nomorUnit: true,
                perumahan: { select: { nama: true } },
              },
            },
          },
        },
      },
    });

    return AgentMapper.toDomain(result);
  }

  async findWithCursorPagination(
    limit: number,
    cursor?: number,
    filters?: AgentFilterDTO,
  ): Promise<CursorPaginatedData> {
    const where: Prisma.AgentWhereInput = {};

    if (filters?.search) {
      where.OR = [
        { nama: { contains: filters.search } },
        { nik: { contains: filters.search } },
      ];
    }

    let orderByClause: Prisma.AgentOrderByWithRelationInput[] = [
      { nama: "asc" },
    ];

    if (filters?.orderBy) {
      const { field, direction } = filters.orderBy;
      const validFields = ["nama", "nik", "createdAt"];
      if (validFields.includes(field)) {
        orderByClause = [{ [field]: direction }, { id: "asc" }];
      }
    }

    const items = await this.db.agent.findMany({
      take: limit + 1,
      ...(cursor && { skip: 1, cursor: { id: cursor } }),
      where,
      orderBy: orderByClause,
      include: {
        pics: true,
        penjualan: {
          orderBy: { createdAt: "desc" },
          select: {
            id: true,
            noTransaksi: true,
            tanggal: true,
            hargaJual: true,
            status: true,
            customer: { select: { nama: true } },
            kavling: {
              select: {
                blok: true,
                nomorUnit: true,
                perumahan: { select: { nama: true } },
              },
            },
          },
        },
      },
    });

    let hasNextPage = false;
    if (items.length > limit) {
      hasNextPage = true;
      items.pop();
    }

    return {
      items: items.map((item) => AgentMapper.toDomain(item)),
      meta: {
        nextCursor: hasNextPage ? (items.at(-1)?.id ?? null) : null,
        hasNextPage,
      },
    };
  }

  async delete(id: number): Promise {
    const existing = await this.findById(id);
    if (!existing) {
      throw new NotFoundError("Agent tidak ditemukan");
    }

    await this.db.agent.delete({ where: { id } });
  }
}

import { Prisma } from "@prisma/client";
import type { PrismaClient, BankRekeningPt } from "@prisma/client";
import type { IBankRekeningPtRepository } from "./IBankRekeningPtRepo.js";
import type {
  CreateBankRekeningPtDTO,
  UpdateBankRekeningPtDTO,
  BankRekeningPtFilterDTO,
} from "../dtos/BankRekeningPtDTO.js";
import type { CursorPaginatedData } from "../../types/response.js";
import { NotFoundError } from "../errors/NotFoundError.js";
import { ConflictError } from "../errors/ConflictError.js";

export class BankRekeningPtRepository implements IBankRekeningPtRepository {
  constructor(private readonly db: PrismaClient) {}

  async create(data: CreateBankRekeningPtDTO): Promise {
    const checkDuplicate = await this.db.bankRekeningPt.findFirst({
      where: { noRekening: data.noRekening },
    });
    if (checkDuplicate) {
      throw new ConflictError("Nomor rekening sudah terdaftar");
    }

    const result = await this.db.bankRekeningPt.create({
      data: {
        perumahanId: data.perumahanId,
        namaBank: data.namaBank,
        noRekening: data.noRekening,
        atasNama: data.atasNama,
      },
    });
    return result;
  }

  async findById(id: number): Promise {
    return await this.db.bankRekeningPt.findUnique({
      where: { id },
      include: { perumahan: true },
    });
  }

  async update(
    id: number,
    data: UpdateBankRekeningPtDTO,
  ): Promise {
    const existing = await this.findById(id);
    if (!existing) throw new NotFoundError("Rekening tidak ditemukan");

    if (data.noRekening && data.noRekening !== existing.noRekening) {
      const checkDuplicate = await this.db.bankRekeningPt.findFirst({
        where: { noRekening: data.noRekening },
      });
      if (checkDuplicate) {
        throw new ConflictError("Nomor rekening sudah digunakan");
      }
    }

    const updateData: Prisma.BankRekeningPtUncheckedUpdateInput = {};
    if (data.perumahanId !== undefined)
      updateData.perumahanId = data.perumahanId;
    if (data.namaBank !== undefined) updateData.namaBank = data.namaBank;
    if (data.noRekening !== undefined) updateData.noRekening = data.noRekening;
    if (data.atasNama !== undefined) updateData.atasNama = data.atasNama;

    return await this.db.bankRekeningPt.update({
      where: { id },
      data: updateData,
    });
  }
  async findWithCursorPagination(
    limit: number,
    cursor?: number,
    filters?: BankRekeningPtFilterDTO,
  ): Promise<CursorPaginatedData> {
    const where: Prisma.BankRekeningPtWhereInput = {};

    if (filters?.startDate || filters?.endDate) {
      where.createdAt = {};
      if (filters.startDate) where.createdAt.gte = new Date(filters.startDate);
      if (filters.endDate) where.createdAt.lte = new Date(filters.endDate);
    }

    if (filters?.search) {
      where.OR = [
        { namaBank: { contains: filters.search } },
        { atasNama: { contains: filters.search } },
        { noRekening: { contains: filters.search } },
      ];
    }

    let orderByClause: Prisma.BankRekeningPtOrderByWithRelationInput[] = [
      { createdAt: "desc" },
      { id: "asc" },
    ];

    if (filters?.orderBy) {
      const { field, direction } = filters.orderBy;
      const validFields = ["namaBank", "atasNama", "noRekening", "createdAt"];
      if (validFields.includes(field)) {
        orderByClause = [{ [field]: direction }, { id: "asc" }];
      }
    }

    const items = await this.db.bankRekeningPt.findMany({
      take: limit + 1,
      ...(cursor && { skip: 1, cursor: { id: cursor } }),
      where,
      orderBy: orderByClause,
      include: { perumahan: true },
    });

    let hasNextPage = false;
    if (items.length > limit) {
      hasNextPage = true;
      items.pop();
    }

    const nextCursor = hasNextPage ? (items.at(-1)?.id ?? null) : null;

    return {
      items,
      meta: { nextCursor, hasNextPage },
    };
  }

  async delete(id: number): Promise {
    const existing = await this.findById(id);
    if (!existing) throw new NotFoundError("Rekening tidak ditemukan");

    try {
      await this.db.bankRekeningPt.delete({ where: { id } });
    } catch (error) {
      if (
        error instanceof Prisma.PrismaClientKnownRequestError &&
        error.code === "P2003"
      ) {
        throw new ConflictError(
          "Rekening tidak dapat dihapus karena sudah terhubung dengan data SPR.",
        );
      }
      throw error;
    }
  }
}

import { Prisma } from "@prisma/client";
import type { PrismaClient, Customer } from "@prisma/client";
import type { ICustomerRepository } from "./ICustomerRepo.js";
import type {
  CreateCustomerDTO,
  UpdateCustomerDTO,
  CustomerFilterDTO,
} from "../dtos/CustomerDTO.js";
import type { CursorPaginatedData } from "../../types/response.js";
import { NotFoundError } from "../errors/NotFoundError.js";
import { ConflictError } from "../errors/ConflictError.js";

export class CustomerRepository implements ICustomerRepository {
  constructor(private readonly db: PrismaClient) {}

  async create(data: CreateCustomerDTO): Promise {
    const existingCustomer = await this.findByNik(data.nikKtp);
    if (existingCustomer) {
      throw new ConflictError("Customer dengan NIK tersebut sudah terdaftar");
    }

    return await this.db.customer.create({
      data: {
        nikKtp: data.nikKtp,
        nama: data.nama,
        noHp: data.noHp,
        email: data.email ?? null,
        pekerjaan: data.pekerjaan ?? null,
        perusahaan: data.perusahaan ?? null,
        bank: data.bank ?? null,
        alamatKoresponden: data.alamatKoresponden ?? null,
        alamatKtp: data.alamatKtp,
        alamatTinggal: data.alamatTinggal ?? null,
      },
    });
  }

  async findById(id: number): Promise {
    return await this.db.customer.findUnique({ where: { id } });
  }

  async findByNik(nikKtp: string): Promise {
    return await this.db.customer.findUnique({ where: { nikKtp } });
  }

  async update(id: number, data: UpdateCustomerDTO): Promise {
    const existing = await this.findById(id);
    if (!existing) throw new NotFoundError("Customer tidak ditemukan");

    if (data.nikKtp && data.nikKtp !== existing.nikKtp) {
      const checkDuplicate = await this.findByNik(data.nikKtp);
      if (checkDuplicate) {
        throw new ConflictError("NIK sudah digunakan oleh customer lain");
      }
    }

    const updateData: Prisma.CustomerUncheckedUpdateInput = {};
    if (data.userId !== undefined) updateData.userId = data.userId;
    if (data.nikKtp !== undefined) updateData.nikKtp = data.nikKtp;
    if (data.nama !== undefined) updateData.nama = data.nama;
    if (data.noHp !== undefined) updateData.noHp = data.noHp;
    if (data.email !== undefined) updateData.email = data.email ?? null;
    if (data.pekerjaan !== undefined)
      updateData.pekerjaan = data.pekerjaan ?? null;
    if (data.perusahaan !== undefined)
      updateData.perusahaan = data.perusahaan ?? null;
    if (data.bank !== undefined) updateData.bank = data.bank ?? null;
    if (data.alamatKoresponden !== undefined)
      updateData.alamatKoresponden = data.alamatKoresponden ?? null;
    if (data.alamatKtp !== undefined) updateData.alamatKtp = data.alamatKtp;
    if (data.alamatTinggal !== undefined)
      updateData.alamatTinggal = data.alamatTinggal ?? null;
    if (data.fileKtp !== undefined) updateData.fileKtp = data.fileKtp ?? null;
    if (data.fileKk !== undefined) updateData.fileKk = data.fileKk ?? null;
    if (data.fileNpwp !== undefined)
      updateData.fileNpwp = data.fileNpwp ?? null;

    if (data.dokumenLainnya !== undefined)
      updateData.dokumenLainnya = data.dokumenLainnya ?? Prisma.DbNull;

    return await this.db.customer.update({
      where: { id },
      data: updateData,
    });
  }
  async findWithCursorPagination(
    limit: number,
    cursor?: number,
    filters?: CustomerFilterDTO,
  ): Promise<CursorPaginatedData> {
    const where: Prisma.CustomerWhereInput = {};

    if (filters?.startDate || filters?.endDate) {
      where.createdAt = {};
      if (filters.startDate) where.createdAt.gte = new Date(filters.startDate);
      if (filters.endDate) where.createdAt.lte = new Date(filters.endDate);
    }

    if (filters?.search) {
      where.OR = [
        { nama: { contains: filters.search } },
        { nikKtp: { contains: filters.search } },
        { noHp: { contains: filters.search } },
      ];
    }

    let orderByClause: Prisma.CustomerOrderByWithRelationInput[] = [
      { createdAt: "desc" },
      { id: "asc" },
    ];

    if (filters?.orderBy) {
      const { field, direction } = filters.orderBy;
      const validFields = ["nama", "nikKtp", "noHp", "createdAt"];
      if (validFields.includes(field)) {
        orderByClause = [{ [field]: direction }, { id: "asc" }];
      }
    }

    const items = await this.db.customer.findMany({
      take: limit + 1,
      ...(cursor && { skip: 1, cursor: { id: cursor } }),
      where,
      orderBy: orderByClause,
    });

    let hasNextPage = false;
    if (items.length > limit) {
      hasNextPage = true;
      items.pop();
    }

    const nextCursor = hasNextPage ? (items.at(-1)?.id ?? null) : null;

    return { items, meta: { nextCursor, hasNextPage } };
  }
  async delete(id: number): Promise {
    const existing = await this.findById(id);
    if (!existing) throw new NotFoundError("Customer tidak ditemukan");

    try {
      await this.db.customer.delete({ where: { id } });
    } catch (error) {
      if (
        error instanceof Prisma.PrismaClientKnownRequestError &&
        error.code === "P2003"
      ) {
        throw new ConflictError(
          "Customer tidak dapat dihapus karena sudah memiliki data SPR/Booking.",
        );
      }
      throw error;
    }
  }
  async findByUserId(userId: number): Promise {
    return await this.db.customer.findFirst({ where: { userId } });
  }
}

import type { Prisma } from "@prisma/client";
import type { PrismaClient } from "@prisma/client";
import type { ITagihanRepository } from "./ITagihanRepo.js";
import type {
  CreateTagihanDTO,
  UpdateTagihanDTO,
  TagihanFilterDTO,
  TagihanResponseDTO,
} from "../dtos/TagihanDTO.js";
import type { CursorPaginatedData } from "../../types/response.js";
import { NotFoundError } from "../errors/NotFoundError.js";
import { TagihanMapper } from "../../infrastructure/mapper/TagihanMapper.js";

const tagihanIncludeRelations = {
  customer: { select: { nama: true } },
  penjualan: {
    include: {
      kavling: {
        include: {
          perumahan: { select: { nama: true } },
          rekeningTujuan: true,
        },
      },
      rekeningTujuan: true,
    },
  },
} satisfies Prisma.TagihanInclude;

export class TagihanRepository implements ITagihanRepository {
  constructor(private readonly db: PrismaClient) {}

  async count(): Promise {
    return await this.db.tagihan.count();
  }

  async create(
    data: CreateTagihanDTO,
    noTagihan: string,
  ): Promise {
    const parseDate = (d: string | Date) => new Date(d);

    const result = await this.db.tagihan.create({
      data: {
        noTagihan,
        customerId: data.customerId,
        penjualanId: data.penjualanId,
        pembayaran: data.pembayaran,
        nominal: data.nominal,
        jatuhTempo: parseDate(data.jatuhTempo),
        reminderBerikutnya: data.reminderBerikutnya
          ? parseDate(data.reminderBerikutnya)
          : null,
        status: "BELUM_BAYAR",
      },
      include: tagihanIncludeRelations,
    });

    return TagihanMapper.toDomain(result);
  }

  async findById(id: number): Promise {
    const result = await this.db.tagihan.findUnique({
      where: { id },
      include: tagihanIncludeRelations,
    });
    if (!result) return null;
    return TagihanMapper.toDomain(result);
  }

  async update(
    id: number,
    data: UpdateTagihanDTO,
  ): Promise {
    const existing = await this.findById(id);
    if (!existing) throw new NotFoundError("Tagihan tidak ditemukan");

    const updateData: Prisma.TagihanUpdateInput = {};
    if (data.pembayaran !== undefined) updateData.pembayaran = data.pembayaran;
    if (data.nominal !== undefined) updateData.nominal = data.nominal;
    if (data.status !== undefined) updateData.status = data.status;
    if (data.fileBukti !== undefined) updateData.fileBukti = data.fileBukti;
    if (data.jatuhTempo !== undefined)
      updateData.jatuhTempo = new Date(data.jatuhTempo);
    if (data.reminderBerikutnya !== undefined) {
      updateData.reminderBerikutnya = data.reminderBerikutnya
        ? new Date(data.reminderBerikutnya)
        : null;
    }

    const result = await this.db.tagihan.update({
      where: { id },
      data: updateData,
      include: tagihanIncludeRelations,
    });

    return TagihanMapper.toDomain(result);
  }

  async findWithCursorPagination(
    limit: number,
    cursor?: number,
    filters?: TagihanFilterDTO,
  ): Promise<CursorPaginatedData> {
    const where: Prisma.TagihanWhereInput = {
      penjualan: {
        status: {
          not: "BATAL",
        },
      },
    };

    if (filters?.customerId) where.customerId = filters.customerId;
    if (filters?.penjualanId) where.penjualanId = filters.penjualanId;
    if (filters?.status) where.status = filters.status;

    if (filters?.search) {
      where.OR = [
        { noTagihan: { contains: filters.search } },
        { pembayaran: { contains: filters.search } },
        { customer: { nama: { contains: filters.search } } },
      ];
    }

    const items = await this.db.tagihan.findMany({
      take: limit + 1,
      ...(cursor && { skip: 1, cursor: { id: cursor } }),
      where,
      orderBy: [{ createdAt: "desc" }],
      include: tagihanIncludeRelations,
    });

    let hasNextPage = false;
    if (items.length > limit) {
      hasNextPage = true;
      items.pop();
    }

    return {
      items: items.map((item) => TagihanMapper.toDomain(item as any)),
      meta: {
        nextCursor: hasNextPage ? (items.at(-1)?.id ?? null) : null,
        hasNextPage,
      },
    };
  }

  async delete(id: number): Promise {
    const existing = await this.findById(id);
    if (!existing) throw new NotFoundError("Tagihan tidak ditemukan");
    await this.db.tagihan.delete({ where: { id } });
  }
}

