import type { PrismaClient } from "@prisma/client";
import type {
  DashboardResponseDTO,
  DocumentAlertDTO,
} from "../../../domain/dtos/DashboardDTO.js";

export class GetDashboardSummaryUseCase {
  constructor(private readonly db: PrismaClient) {}

  async execute(): Promise {
    const now = new Date();

    const totalTagihanLunas = await this.db.tagihan.aggregate({
      _sum: { nominal: true },
      where: { status: "LUNAS" },
    });

    const kavlingTerjualCount = await this.db.kavling.count({
      where: { status: "TERJUAL" },
    });

    const totalKavlingCount = await this.db.kavling.count();

    const tagihanJatuhTempo = await this.db.tagihan.aggregate({
      _sum: { nominal: true },
      where: { status: "BELUM_BAYAR", jatuhTempo: { lt: now } },
    });

    const customerJatuhTempo = await this.db.tagihan.groupBy({
      by: ["customerId"],
      where: { status: "BELUM_BAYAR", jatuhTempo: { lt: now } },
    });

    const proyekAktifCount = await this.db.spk.count();

    const progressProyek = await this.db.progressProyek.aggregate({
      _avg: { persentase: true },
    });

    const recentPenjualan = await this.db.penjualan.findMany({
      take: 5,
      orderBy: { createdAt: "desc" },
      include: {
        customer: { select: { nama: true } },
        kavling: { select: { blok: true, nomorUnit: true } },
      },
    });

    const recentTransactions = recentPenjualan.map((p) => ({
      id: p.noTransaksi,
      customer: p.customer.nama,
      kavling: `${p.kavling.blok} - ${p.kavling.nomorUnit}`,
      type: p.caraPembayaran,
      amount: Number(p.hargaJual),
      status: p.status,
      date: p.createdAt.toISOString().substring(0, 10),
    }));

    const latestProgress = await this.db.progressProyek.findMany({
      take: 5,
      orderBy: { tanggalLaporan: "desc" },
      include: {
        kavling: {
          include: {
            penjualan: {
              include: { customer: { select: { nama: true } } },
              take: 1,
            },
          },
        },
      },
    });

    const progressData = latestProgress.map((prog) => ({
      kavling: `Blok ${prog.kavling.blok} - ${prog.kavling.nomorUnit}`,
      customer: prog.kavling.penjualan[0]?.customer?.nama ?? "Unknown",
      progress: prog.persentase,
      tahap: prog.tahapanPekerjaan,
      isLate: false,
    }));

    const topAgentsData = await this.db.penjualan.groupBy({
      by: ["agentId"],
      _count: { id: true },
      where: { agentId: { not: null }, status: { in: ["LUNAS", "PROSES"] } },
      orderBy: { _count: { id: "desc" } },
      take: 3,
    });

    const topAgents = await Promise.all(
      topAgentsData.map(async (ta) => {
        const agent = await this.db.agent.findUnique({
          where: { id: ta.agentId! },
          select: { nama: true },
        });

        const fee = await this.db.feeAgent.aggregate({
          _sum: { closingNominal: true },
          where: { agentId: ta.agentId! },
        });

        return {
          name: agent?.nama ?? "Unknown",
          closing: ta._count.id,
          feeStatus: `Rp ${(fee._sum.closingNominal ?? 0).toLocaleString("id-ID")}`,
        };
      }),
    );

    const missingDocsCustomers = await this.db.customer.findMany({
      where: {
        OR: [{ fileKtp: null }, { fileKk: null }, { fileNpwp: null }],
      },
      include: {
        penjualan: {
          include: { kavling: { select: { blok: true, nomorUnit: true } } },
          take: 1,
        },
      },
      take: 5,
    });

    const documentAlerts: DocumentAlertDTO[] = missingDocsCustomers.map(
      (cust) => {
        const missing = [];
        if (!cust.fileKtp) missing.push("KTP");
        if (!cust.fileKk) missing.push("KK");
        if (!cust.fileNpwp) missing.push("NPWP");

        return {
          customer: cust.nama,
          kavling: cust.penjualan[0]
            ? `Blok ${cust.penjualan[0].kavling.blok} - ${cust.penjualan[0].kavling.nomorUnit}`
            : "Belum Beli",
          missing,
        };
      },
    );

    return {
      stats: {
        totalPendapatan: Number(totalTagihanLunas._sum.nominal ?? 0),
        kavlingTerjual: kavlingTerjualCount,
        totalKavling: totalKavlingCount,
        tagihanJatuhTempo: Number(tagihanJatuhTempo._sum.nominal ?? 0),
        customerJatuhTempo: customerJatuhTempo.length,
        proyekAktif: proyekAktifCount,
        rataRataProgress: Number(progressProyek._avg.persentase ?? 0),
      },
      recentTransactions,
      progressData,
      topAgents,
      documentAlerts,
    };
  }
}

import type { PrismaClient } from "@prisma/client";
import { NotFoundError } from "../../../domain/errors/NotFoundError.js";
import { ConflictError } from "../../../domain/errors/ConflictError.js";
import type { CloudinaryService } from "../../../infrastructure/external/CloudinaryService.js";
import type { GenerateSprPdfUseCase } from "./GenerateSprPdfUseCase.js";

export class ApproveGantiKavlingUseCase {
  constructor(
    private readonly db: PrismaClient,
    private readonly cloudinaryService: CloudinaryService,
    private readonly generateSprPdfUseCase: GenerateSprPdfUseCase,
  ) {}

  async execute(riwayatId: number, approvedById: number, isApproved: boolean) {
    const result = await this.db.$transaction(async (tx) => {
      const riwayat = await tx.riwayatGantiKavling.findUnique({
        where: { id: riwayatId },
        include: {
          penjualan: { include: { kavling: true, detailKavlingPajak: true } },
          kavlingBaru: true,
          kavlingLama: true,
        },
      });

      if (!riwayat)
        throw new NotFoundError("Pengajuan ganti kavling tidak ditemukan");
      if (riwayat.status !== "PENDING")
        throw new ConflictError("Pengajuan ini sudah diproses");

      if (!isApproved) {
        await tx.kavling.update({
          where: { id: riwayat.kavlingBaruId },
          data: { status: "AVAILABLE" },
        });

        return await tx.riwayatGantiKavling.update({
          where: { id: riwayatId },
          data: { status: "REJECTED", approvedById },
          include: { penjualan: true, kavlingLama: true, kavlingBaru: true },
        });
      }

      await tx.kavling.update({
        where: { id: riwayat.kavlingLamaId },
        data: { status: "AVAILABLE" },
      });

      await tx.kavling.update({
        where: { id: riwayat.kavlingBaruId },
        data: { status: riwayat.penjualan.kavling.status },
      });

      const oldPenjualan = riwayat.penjualan;
      const hargaDasarBaru = Number(riwayat.kavlingBaru.hargaDasar);
      const diskon = Number(oldPenjualan.diskonPenjualan ?? 0);
      const bookingFee = Number(oldPenjualan.bookingFee ?? 0);

      const plafonAwal = hargaDasarBaru - diskon - bookingFee;

      const existingTambahan = await tx.tagihan.findMany({
        where: {
          penjualanId: riwayat.penjualanId,
          noTagihan: { startsWith: "INV-ADD-" },
        },
      });
      const totalBiayaTambahan = existingTambahan.reduce(
        (sum, t) => sum + Number(t.nominal),
        0,
      );

      let biayaKpr = 0;
      let plafonKredit = 0;
      let nilaiPengajuanKpr = 0;
      let dp = 0;
      let hargaJual = 0;

      if (
        oldPenjualan.caraPembayaran === "CASH_KERAS" ||
        oldPenjualan.caraPembayaran === "CASH_BERTAHAP"
      ) {
        hargaJual = hargaDasarBaru - diskon;
      } else if (oldPenjualan.caraPembayaran === "KPR") {
        biayaKpr = plafonAwal * 0.06;
        plafonKredit = plafonAwal + biayaKpr;

        nilaiPengajuanKpr = plafonKredit - totalBiayaTambahan;

        const baseHargaJual = plafonKredit / 0.9;
        dp = oldPenjualan.dp ? Number(oldPenjualan.dp) : baseHargaJual * 0.1;
        hargaJual = baseHargaJual + diskon;
      }

      await tx.penjualan.update({
        where: { id: riwayat.penjualanId },
        data: {
          kavlingId: riwayat.kavlingBaruId,
          hargaDasar: hargaDasarBaru,
          plafonAwal: plafonAwal,
          biayaKpr: biayaKpr > 0 ? biayaKpr : null,
          plafonKredit: plafonKredit > 0 ? plafonKredit : null,
          nilaiPengajuanKpr: nilaiPengajuanKpr > 0 ? nilaiPengajuanKpr : null,
          dp: dp > 0 ? dp : null,
          hargaJual: hargaJual,
        },
      });

      if (riwayat.penjualan.detailKavlingPajak) {
        await tx.detailKavlingPajak.update({
          where: { penjualanId: riwayat.penjualanId },
          data: { luasBangunan: riwayat.kavlingBaru.luasBangunan.toString() },
        });
      }

      return await tx.riwayatGantiKavling.update({
        where: { id: riwayatId },
        data: { status: "APPROVED", approvedById },
        include: { penjualan: true, kavlingLama: true, kavlingBaru: true },
      });
    });

    if (isApproved && result.status === "APPROVED" && result.penjualan) {
      try {
        const oldPenjualan = result.penjualan;

        if (oldPenjualan.fileSpr) {
          await this.db.riwayatSpr.create({
            data: {
              penjualanId: oldPenjualan.id,
              fileSpr: oldPenjualan.fileSpr,
              keterangan: `Ganti Kavling: Blok ${result.kavlingLama.blok}-${result.kavlingLama.nomorUnit} -> Blok ${result.kavlingBaru.blok}-${result.kavlingBaru.nomorUnit}`,
            },
          });
        }

        const pdfBuffer = await this.generateSprPdfUseCase.execute(
          oldPenjualan.id,
        );
        const sprUrl = await this.cloudinaryService.uploadFile(
          pdfBuffer,
          "bumantara/spr",
        );

        await this.db.penjualan.update({
          where: { id: oldPenjualan.id },
          data: { fileSpr: sprUrl },
        });
      } catch (error) {
        console.error("Gagal auto-generate SPR setelah Ganti Kavling:", error);
      }
    }

    return result;
  }
}

import type { PrismaClient } from "@prisma/client";
import { NotFoundError } from "../../../domain/errors/NotFoundError.js";
import { ConflictError } from "../../../domain/errors/ConflictError.js";

export class CancelPenjualanUseCase {
  constructor(private readonly db: PrismaClient) {}

  async execute(
    noTransaksi: string,
    alasanBatal: string,
    requestedById: number,
  ) {
    return await this.db.$transaction(async (tx) => {
      const penjualan = await tx.penjualan.findUnique({
        where: { noTransaksi },
        include: { pengajuanBatal: { where: { status: "PENDING" } } },
      });

      if (!penjualan) throw new NotFoundError("Data Penjualan tidak ditemukan");
      if (penjualan.status === "BATAL")
        throw new ConflictError("Penjualan sudah dibatalkan sebelumnya");
      if (penjualan.status === "LUNAS")
        throw new ConflictError(
          "Penjualan Lunas tidak bisa dibatalkan sembarangan",
        );
      if (penjualan.pengajuanBatal.length > 0) {
        throw new ConflictError(
          "Sudah ada pengajuan pembatalan yang menunggu persetujuan (PENDING).",
        );
      }

      return await tx.pengajuanBatal.create({
        data: {
          penjualanId: penjualan.id,
          alasan: alasanBatal,
          status: "PENDING",
          requestedById: requestedById,
        },
      });
    });
  }
}

