        pjBiayaBbn: Number(row[46]) || 0,
        pjBiayaAjb: Number(row[47]) || 0,
        pjBiayaAppraisal: Number(row[48]) || 0,
        pjBphtb: Number(row[49]) || 0,
        pjLainLain: Number(row[50]) || 0,
        pjNilaiPenyerahan: Number(row[52]) || 0,
