}

import { StatusCodes } from "http-status-codes";
import { AppError } from "../../../domain/errors/AppError.js";
import type { PrismaClient } from "@prisma/client";
import { NotFoundError } from "../../../domain/errors/NotFoundError.js";

export class VerifyDocumentUseCase {
  constructor(private readonly db: PrismaClient) {}

  async execute(documentNumber: string) {
    if (!documentNumber) {
      throw new AppError(StatusCodes.BAD_REQUEST, "Nomor dokumen tidak valid");
    }

    if (
      documentNumber.startsWith("INV-") ||
      documentNumber.startsWith("KWT-")
    ) {
      return await this.handleTagihan(documentNumber);
    }

    if (documentNumber.startsWith("TRX-")) {
      const penjualan = await this.db.penjualan.findUnique({
        where: { noTransaksi: documentNumber },
        include: {
          customer: { select: { nama: true, noHp: true, alamatKtp: true } },
          kavling: {
            include: {
              perumahan: { select: { nama: true, logo: true } },
              rekeningTujuan: true,
            },
          },
        },
      });

      if (!penjualan) throw new NotFoundError("Dokumen SPR tidak ditemukan");

      return {
        type: "SPR",
        data: {
          noDokumen: penjualan.noTransaksi,
          tanggalTransaksi: penjualan.tanggal,
          status: penjualan.status,
          hargaJual: Number(penjualan.hargaJual),
          dp: Number(penjualan.dp ?? 0),
          bookingFee: Number(penjualan.bookingFee ?? 0),
          caraPembayaran: penjualan.caraPembayaran
            ? penjualan.caraPembayaran.replace(/_/g, " ")
            : null,
          bank: penjualan.bank ?? "",
          pembuat: penjualan.createdBy ?? "Admin",
          customer: {
            nama: penjualan.customer.nama,
            noHp: penjualan.customer.noHp,
            alamat: penjualan.customer.alamatKtp,
          },
          kavling: {
            perumahan: penjualan.kavling.perumahan.nama,
            logoPerumahan: penjualan.kavling.perumahan.logo,
            blokUnit: `Blok ${penjualan.kavling.blok}-${penjualan.kavling.nomorUnit}`,
            tipe: penjualan.kavling.namaTipe,
            rekeningTujuan: penjualan.kavling.rekeningTujuan,
          },
        },
      };
    }

    throw new AppError(
      StatusCodes.BAD_REQUEST,
      "Format nomor dokumen tidak dikenali",
    );
  }

  private async handleTagihan(requestedNumber: string) {
    const isRequestingKwitansi = requestedNumber.startsWith("KWT-");

    const searchNoTagihan = requestedNumber.replace(/^KWT-/, "INV-");

    const tagihan = await this.db.tagihan.findUnique({
      where: { noTagihan: searchNoTagihan },
      include: {
        customer: { select: { nama: true, noHp: true, alamatKtp: true } },
        penjualan: {
          include: {
            kavling: {
              include: {
                perumahan: { select: { nama: true, logo: true } },
                rekeningTujuan: {
                  select: { namaBank: true, noRekening: true, atasNama: true },
                },
              },
            },
          },
        },
      },
    });

    if (!tagihan) throw new NotFoundError("Data tagihan tidak ditemukan");

    const totalTerbayarAgg = await this.db.tagihan.aggregate({
      where: { penjualanId: tagihan.penjualanId, status: "LUNAS" },
      _sum: { nominal: true },
    });

    const totalTerbayar = Number(totalTerbayarAgg._sum.nominal ?? 0);
    const hargaJual = Number(tagihan.penjualan.hargaJual);
    const sisaBelumDibayar = Math.max(0, hargaJual - totalTerbayar);

    const documentType = isRequestingKwitansi ? "KWITANSI" : "INVOICE";

    return {
      type: documentType,
      data: {
        noDokumen: requestedNumber,
        pembayaran: tagihan.pembayaran,
        nominal: Number(tagihan.nominal),
        jatuhTempo: tagihan.jatuhTempo,
        status: tagihan.status,
        tanggalDibuat: tagihan.createdAt,
        pembuat: tagihan.penjualan.createdBy ?? "Admin",
        customer: {
          nama: tagihan.customer.nama,
          noHp: tagihan.customer.noHp,
          alamat: tagihan.customer.alamatKtp,
        },
        kavling: {
          perumahan: tagihan.penjualan.kavling.perumahan.nama,
          logoPerumahan: tagihan.penjualan.kavling.perumahan.logo,
          blok: tagihan.penjualan.kavling.blok,
          nomorUnit: tagihan.penjualan.kavling.nomorUnit,
          tipe: tagihan.penjualan.kavling.namaTipe,
          rekeningTujuan: tagihan.penjualan.kavling.rekeningTujuan,
        },
        transaksi: {
          caraPembayaran: tagihan.penjualan.caraPembayaran
            ? tagihan.penjualan.caraPembayaran.replace(/_/g, " ")
            : null,
          bank: tagihan.penjualan.bank ?? "",
          hargaJual: hargaJual,
          sisaBelumDibayar: sisaBelumDibayar,
        },
        ttdData: tagihan.ttdData ?? null,
      },
    };
  }
}

import { Prisma } from "@prisma/client";
import type { PrismaClient } from "@prisma/client";
import type { IKavlingRepository } from "./IKavlingRepo.js";
import type { KavlingEntity } from "../entities/Kavling.js";
import type {
  CreateKavlingDTO,
  UpdateKavlingDTO,
  KavlingFilterDTO,
} from "../dtos/KavlingDTO.js";
import type { OffsetPaginatedData } from "../../types/response.js";
import { NotFoundError } from "../errors/NotFoundError.js";
import { ConflictError } from "../errors/ConflictError.js";
import { KavlingMapper } from "../../infrastructure/mapper/KavlingMapper.js";
export class KavlingRepository implements IKavlingRepository {
  constructor(private readonly db: PrismaClient) {}
  async create(data: CreateKavlingDTO): Promise {
    try {
      const existing = await this.db.kavling.findFirst({
        where: {
          perumahanId: data.perumahanId,
          blok: data.blok,
          nomorUnit: data.nomorUnit,
        },
      });
      if (existing) {
        throw new ConflictError(
          `Kavling Blok ${data.blok} Nomor ${data.nomorUnit} sudah terdaftar di perumahan ini.`,
        );
      }
      const createData: Prisma.KavlingUncheckedCreateInput = {
        perumahanId: data.perumahanId,
        blok: data.blok,
        nomorUnit: data.nomorUnit,
        namaTipe: data.namaTipe,
        luasBangunan: data.luasBangunan,
        luasTanah: data.luasTanah,
        hargaDasar: data.hargaDasar,
        rekeningTujuanId: data.rekeningTujuanId ?? null,
        filePbg: data.filePbg ?? null,
        fileSertifikatTanah: data.fileSertifikatTanah ?? null,
        fileNopPbb: data.fileNopPbb ?? null,
      };
      if (data.status !== undefined) {
        createData.status = data.status;
      }
      const result = await this.db.kavling.create({
        data: createData,
        include: { perumahan: true, rekeningTujuan: true },
      });
      return KavlingMapper.toDomain(result);
    } catch (error) {
      if (
        error instanceof Prisma.PrismaClientKnownRequestError &&
        error.code === "P2002"
      ) {
        throw new ConflictError(
          `Kavling Blok ${data.blok} Nomor ${data.nomorUnit} sudah terdaftar di perumahan ini.`,
        );
      }
      console.error(error);
      throw error;
    }
  }
  async findById(id: number): Promise {
    const result = await this.db.kavling.findUnique({
      where: { id },
      include: { perumahan: true, rekeningTujuan: true },
    });
    if (!result) return null;
    return KavlingMapper.toDomain(result);
  }
  async update(id: number, data: UpdateKavlingDTO): Promise {
    const existing = await this.findById(id);
    if (!existing) throw new NotFoundError("Kavling tidak ditemukan");

    const updateData: Prisma.KavlingUncheckedUpdateInput = {};
    if (data.perumahanId !== undefined)
      updateData.perumahanId = data.perumahanId;
    if (data.blok !== undefined) updateData.blok = data.blok;
    if (data.nomorUnit !== undefined) updateData.nomorUnit = data.nomorUnit;
    if (data.namaTipe !== undefined) updateData.namaTipe = data.namaTipe;
    if (data.luasBangunan !== undefined)
      updateData.luasBangunan = data.luasBangunan;
    if (data.luasTanah !== undefined) updateData.luasTanah = data.luasTanah;
    if (data.hargaDasar !== undefined) updateData.hargaDasar = data.hargaDasar;
    if (data.status !== undefined) updateData.status = data.status;
    if (data.rekeningTujuanId !== undefined)
      updateData.rekeningTujuanId = data.rekeningTujuanId ?? null;
    if (data.filePbg !== undefined) updateData.filePbg = data.filePbg ?? null;
    if (data.fileSertifikatTanah !== undefined)
      updateData.fileSertifikatTanah = data.fileSertifikatTanah ?? null;
    if (data.fileNopPbb !== undefined)
      updateData.fileNopPbb = data.fileNopPbb ?? null;

    try {
      const result = await this.db.kavling.update({
        where: { id },
        data: updateData,
        include: { perumahan: true, rekeningTujuan: true },
      });
      return KavlingMapper.toDomain(result);
    } catch (error) {
      if (
        error instanceof Prisma.PrismaClientKnownRequestError &&
        error.code === "P2002"
      ) {
        throw new ConflictError(
          "Gagal memperbarui: Kombinasi Blok dan Nomor Unit tersebut sudah digunakan oleh kavling lain.",
        );
      }
      throw error;
    }
  }
  async findWithCursorPagination(
    page: number,
    limit: number,
    filters?: KavlingFilterDTO,
  ): Promise<OffsetPaginatedData> {
    const where: Prisma.KavlingWhereInput = {};
    if (filters?.perumahanId) where.perumahanId = filters.perumahanId;
    if (filters?.status) where.status = filters.status;
    if (filters?.search) {
      where.OR = [
        { blok: { contains: filters.search } },
        { nomorUnit: { contains: filters.search } },
        { namaTipe: { contains: filters.search } },
      ];
    }
    let orderByClause: Prisma.KavlingOrderByWithRelationInput[] = [
      { blok: "asc" },
      { nomorUnit: "asc" },
      { id: "desc" },
    ];
    if (filters?.orderBy) {
      const { field, direction } = filters.orderBy;
      const validFields = ["blok", "hargaDasar", "luasBangunan", "luasTanah"];
      if (validFields.includes(field)) {
        orderByClause = [{ [field]: direction }, { id: "asc" }];
      }
    }
    const skip = (page - 1) * limit;
    const summaryWhere: Prisma.KavlingWhereInput | undefined =
      filters?.perumahanId ? { perumahanId: filters.perumahanId } : undefined;
    const [items, totalItems, summaryData] = await Promise.all([
      this.db.kavling.findMany({
        take: limit,
        skip,
        where,
        orderBy: orderByClause,
        include: {
          perumahan: true,
          rekeningTujuan: true,
          penjualan: {
            where: { status: { not: "BATAL" } },
            include: { customer: { select: { nama: true, noHp: true } } },
            take: 1,
          },
        },
      }),
      this.db.kavling.count({ where }),
      this.db.kavling.groupBy({
        by: ["status"],
        _count: { id: true },
        ...(summaryWhere && { where: summaryWhere }),
      }),
    ]);
    const totalPages = Math.ceil(totalItems / limit);
    const summary = summaryData.reduce(
      (acc, curr) => {
        acc[curr.status] = curr._count.id;
        return acc;
      },
      {} as Record,
    );
    return {
      items: items.map((item) => KavlingMapper.toDomain(item)),
      meta: {
        page,
        limit,
        totalItems,
        totalPages,
        hasNextPage: page < totalPages,
        hasPrevPage: page > 1,
        summary,
      },
    };
  }
  async delete(id: number): Promise {
    const existing = await this.findById(id);
    if (!existing) throw new NotFoundError("Kavling tidak ditemukan");
    try {
      await this.db.kavling.delete({ where: { id } });
    } catch (error) {
      if (
        error instanceof Prisma.PrismaClientKnownRequestError &&
        error.code === "P2003"
      ) {
        throw new ConflictError(
          "Kavling tidak dapat dihapus karena sudah ada riwayat transaksi atau progress pembangunan.",
        );
      }
      throw error;
    }
  }
}

import { Router } from "express";
import { authenticate, requireRole } from "../../middlewares/authMiddleware.js";
import { validate } from "../../middlewares/validate.js";
import {
  cancelPenjualanSchema,
  createPenjualanSchema,
  gantiKavlingSchema,
  getPenjualanPaginatedSchema,
  updatePenjualanSchema,
  uploadSignatureSchema,
  approveSchema,
} from "../../validations/penjualanSchema.js";
import type { PenjualanController } from "../controllers/penjualanController.js";
import { upload } from "../../middlewares/upload.js";

export const createPenjualanRoutes = (
  controller: PenjualanController,
): Router => {
  const router = Router();

  router.use(authenticate);

  router.get(
    "/pengajuan-batal",
    requireRole(["ADMIN", "MARKETING"]),
    controller.getPengajuanBatal,
  );
  router.get(
    "/pengajuan-ganti-kavling",
    requireRole(["ADMIN", "MARKETING"]),
    controller.getPengajuanGantiKavling,
  );

  router.post(
    "/pengajuan-batal/:id/approve",
    requireRole(["ADMIN"]),
    validate(approveSchema),
    controller.approveBatal,
  );
  router.post(
    "/pengajuan-ganti-kavling/:id/approve",
    requireRole(["ADMIN"]),
    validate(approveSchema),
    controller.approveGantiKavling,
  );

  router.get(
    "/",
    requireRole(["ADMIN", "MARKETING"]),
    validate(getPenjualanPaginatedSchema),
    controller.getPaginated,
  );
  router.post(
    "/",
    requireRole(["ADMIN", "MARKETING"]),
    validate(createPenjualanSchema),
    controller.create,
  );

  router.patch(
    "/:id/cancel",
    requireRole(["ADMIN", "MARKETING"]),
    validate(cancelPenjualanSchema),
    controller.cancel,
  );
  router.patch(
    "/:id/upload/:type",
    requireRole(["ADMIN", "MARKETING"]),
    upload.single("fileBukti"),
    controller.uploadBukti,
  );
  router.post(
    "/:id/signature",
    requireRole(["ADMIN", "MARKETING"]),
    validate(uploadSignatureSchema),
    controller.uploadSignature,
  );
  router.patch(
    "/:id",
    requireRole(["ADMIN", "MARKETING"]),
    validate(updatePenjualanSchema),
    controller.update,
  );
  router.patch(
    "/:id/ganti-kavling",
    requireRole(["ADMIN", "MARKETING"]),
    validate(gantiKavlingSchema),
    controller.gantiKavling,
  );
  router.post(
    "/:id/generate-spr",
    requireRole(["ADMIN", "MARKETING"]),
    controller.regenerateSpr,
  );

  return router;
};

import { PrismaClient } from "@prisma/client";
import { seedPenjualanReal } from "./seeds/penjualanSeed.ts";
import { seedUser } from "./seeds/userSeed.ts";
import clearDatabase from "./clear.ts";
import { seedKavlingTersedia } from "./seeds/kavlingTersediaSeed.ts";

const prisma = new PrismaClient();

async function main() {
  console.log("Memulai proses seeding...");
  await clearDatabase(prisma);
  await seedUser(prisma);

  await seedPenjualanReal(prisma);
  await seedKavlingTersedia(prisma);
}

main()
  .catch((e) => {
    console.error(e);
    process.exit(1);
  })
  .finally(async () => {
    await prisma.$disconnect();
  });

