import type { Prisma } from "@prisma/client";
import type { PrismaClient } from "@prisma/client";
import type { IDetailKavlingPajakRepository } from "../../../domain/repositories/IDetailKavlingPajakRepo.js";
import type { IKavlingRepository } from "../../../domain/repositories/IKavlingRepo.js";
import type {
  UpdateCustomerKavlingDTO,
  CustomerKavlingFilterDTO,
} from "../../../domain/dtos/CustomerKavlingDTO.js";
import { NotFoundError } from "../../../domain/errors/NotFoundError.js";
import type { CursorPaginatedData } from "../../../types/response.js";
import type {
  CreateDetailKavlingPajakDTO,
  UpdateDetailKavlingPajakDTO,
} from "../../../domain/dtos/DetailKavlingPajakDTO.js";
export class GetCustomerKavlingsPaginatedUseCase {
  constructor(private readonly db: PrismaClient) {}

  async execute(
    limit: number,
    cursor?: number,
    filters?: CustomerKavlingFilterDTO,
  ): Promise<CursorPaginatedData> {
    const where: Prisma.PenjualanWhereInput = {
      status: { in: ["BOOKED", "PROSES", "LUNAS"] },
    };

    if (filters?.search) {
      where.customer = { nama: { contains: filters.search } };
    }

    const items = await this.db.penjualan.findMany({
      take: limit + 1,
      ...(cursor && { skip: 1, cursor: { id: cursor } }),
      where,
      orderBy: [{ id: "desc" }],
      include: {
        customer: { select: { nama: true } },
        kavling: { include: { perumahan: true } },
        detailKavlingPajak: { include: { notaris: true } },
        agent: { select: { nama: true } },
      },
    });

    let hasNextPage = false;
    if (items.length > limit) {
      hasNextPage = true;
      items.pop();
    }

    const mappedItems = items.map((p) => {
      const { id: _, ...restDetailPajak } = p.detailKavlingPajak ?? {};

      return {
        id: p.id.toString(),
        customerId: p.customerId,
        namaCustomer: p.customer?.nama || "-",
        perumahan: p.kavling.perumahan?.nama || "",

        status: p.status,
        statusKavling: p.kavling.status,
        blok: p.kavling.blok,
        unit: p.kavling.nomorUnit,
        tipe: p.kavling.namaTipe,
        luasBangunan: Number(p.kavling.luasBangunan),
        luasTanah: Number(p.kavling.luasTanah),

        hargaDasarKavling: Number(p.kavling.hargaDasar),
        diskonPenjualan: Number(p.diskonPenjualan ?? 0),
        totalHargaJual: Number(p.hargaJual),

        pembiayaan: p.caraPembayaran,
        agent: p.agent?.nama ?? "Nama Agent",

        ...restDetailPajak,

        notarisId: p.detailKavlingPajak?.notarisId ?? "",
        createdBy: p.createdBy ?? "Admin",
      };
    });

    return {
      items: mappedItems,
      meta: {
        nextCursor: hasNextPage ? (items.at(-1)?.id ?? null) : null,
        hasNextPage,
      },
    };
  }
}

export class UpdateCustomerKavlingUseCase {
  constructor(
    private readonly db: PrismaClient,
    private readonly kavlingRepo: IKavlingRepository,
    private readonly detailPajakRepo: IDetailKavlingPajakRepository,
  ) {}

  async execute(penjualanId: number, data: UpdateCustomerKavlingDTO) {
    const penjualan = await this.db.penjualan.findUnique({
      where: { id: penjualanId },
      include: { kavling: true },
    });

    if (!penjualan) {
      throw new NotFoundError("Data Penjualan tidak ditemukan");
    }

    const {
      statusKavling,
      namaTipe,
      luasBangunan,
      luasTanah,
      hargaDasarKavling,
      rekeningTujuanId,
      ...detailPajakData
    } = data;

    if (
      statusKavling !== undefined ||
      namaTipe !== undefined ||
      luasBangunan !== undefined ||
      luasTanah !== undefined ||
      hargaDasarKavling !== undefined ||
      rekeningTujuanId !== undefined
    ) {
      await this.kavlingRepo.update(penjualan.kavlingId, {
        status: statusKavling,
        namaTipe: namaTipe,
        luasBangunan: luasBangunan,
        luasTanah: luasTanah,
        hargaDasar: hargaDasarKavling,
        rekeningTujuanId: rekeningTujuanId ?? undefined,
      });
    }

    const createDataPayload: Record = { penjualanId };
    const updateDataPayload: Record = {};

    if (luasBangunan !== undefined) {
      createDataPayload.luasBangunan = luasBangunan.toString();
      updateDataPayload.luasBangunan = luasBangunan.toString();
    }

    for (const [key, value] of Object.entries(detailPajakData)) {
      if (value !== undefined) {
        createDataPayload[key] = value;
        updateDataPayload[key] = value;
      }
    }

    const existingDetail =
      await this.detailPajakRepo.findByPenjualanId(penjualanId);

    if (existingDetail) {
      await this.detailPajakRepo.update(
        penjualanId,
        updateDataPayload as unknown as UpdateDetailKavlingPajakDTO,
      );
    } else {
      await this.detailPajakRepo.create(
        createDataPayload as unknown as CreateDetailKavlingPajakDTO,
      );
    }

    return {
      success: true,
      message: "Data Kavling Customer berhasil diperbarui",
    };
  }
}

import type { Request, Response } from "express";
import { StatusCodes } from "http-status-codes";
import { sendResponse } from "../../utils/response.js";
import type { TypedRequest } from "../../types/request.js";

import type { CreatePenjualanUseCase } from "../../application/usecases/penjualan/CreatePenjualanUseCase.js";
import type { GetPenjualanPaginatedUseCase } from "../../application/usecases/penjualan/GetPenjualanPaginatedUseCase.js";
import type { CancelPenjualanUseCase } from "../../application/usecases/penjualan/CancelPenjualanUseCase.js";
import type { UploadBuktiPenjualanUseCase } from "../../application/usecases/penjualan/UploadBuktiPenjualanUseCase.js";
import type { SaveSignatureUseCase } from "../../application/usecases/penjualan/SaveSignatureUseCase.js";
import type { UpdatePenjualanUseCase } from "../../application/usecases/penjualan/UpdatePenjualanUseCase.js";
import type { GantiKavlingUseCase } from "../../application/usecases/penjualan/GantiKavlingUseCase.js";
import type { ApproveBatalUseCase } from "../../application/usecases/penjualan/ApproveBatalUseCase.js";
import type { ApproveGantiKavlingUseCase } from "../../application/usecases/penjualan/ApproveGantiKavlingUseCase.js";
import type { GetPengajuanBatalUseCase } from "../../application/usecases/penjualan/GetPengajuanBatalUseCase.js";
import type { GetPengajuanGantiKavlingUseCase } from "../../application/usecases/penjualan/GetPengajuanGantiKavlingUseCase.js";

import type {
  cancelPenjualanSchema,
  createPenjualanSchema,
  gantiKavlingSchema,
  updatePenjualanSchema,
  uploadBuktiPenjualanSchema,
  uploadSignatureSchema,
  approveSchema,
} from "../../validations/penjualanSchema.js";
import { getPenjualanPaginatedSchema } from "../../validations/penjualanSchema.js";
import type {
  CreatePenjualanDTO,
  PenjualanFilterDTO,
} from "../../domain/dtos/PenjualanDTO.js";
import { NotFoundError } from "../../domain/errors/NotFoundError.js";
import type { RegenerateSprUseCase } from "../../application/usecases/penjualan/RegenerateSprUseCase.js";

export class PenjualanController {
  constructor(
    private readonly createUseCase: CreatePenjualanUseCase,
    private readonly getPaginatedUseCase: GetPenjualanPaginatedUseCase,
    private readonly cancelUseCase: CancelPenjualanUseCase,
    private readonly uploadBuktiUseCase: UploadBuktiPenjualanUseCase,
    private readonly saveSignatureUseCase: SaveSignatureUseCase,
    private readonly updateUseCase: UpdatePenjualanUseCase,
    private readonly gantiKavlingUseCase: GantiKavlingUseCase,
    private readonly approveBatalUseCase: ApproveBatalUseCase,
    private readonly approveGantiKavlingUseCase: ApproveGantiKavlingUseCase,
    private readonly getPengajuanBatalUseCase: GetPengajuanBatalUseCase,
    private readonly getPengajuanGantiKavlingUseCase: GetPengajuanGantiKavlingUseCase,
    private readonly regenerateSprUseCase: RegenerateSprUseCase,
  ) {}

  create = async (
    req: TypedRequest,
    res: Response,
  ): Promise => {
    const pembuat = req.user?.username ?? "Admin";
    const userId = req.user?.userId;

    if (!userId) {
      throw new NotFoundError("User tidak ditemukan");
    }

    const result = await this.createUseCase.execute({
      ...req.body,
      createdBy: pembuat,
      userId: userId,
    });

    sendResponse(
      res,
      StatusCodes.CREATED,
      "Data Penjualan berhasil disimpan dan tagihan awal telah dibuat.",
      result,
    );
  };

  getPaginated = async (req: Request, res: Response): Promise => {
    const { page, limit, ...filters } = getPenjualanPaginatedSchema.query.parse(
      req.query,
    );

    const result = await this.getPaginatedUseCase.execute(
      page,
      limit,
      filters as PenjualanFilterDTO & { status?: string },
    );

    sendResponse(
      res,
      StatusCodes.OK,
      "Data penjualan berhasil diambil",
      result,
    );
  };
  cancel = async (
    req: TypedRequest<
      typeof cancelPenjualanSchema.body,
      any,
      typeof cancelPenjualanSchema.params
    >,
    res: Response,
  ): Promise => {
    const { id } = req.params;
    const { alasanBatal } = req.body;
    const userId = req.user!.userId;

    const result = await this.cancelUseCase.execute(id, alasanBatal, userId);
    sendResponse(
      res,
      StatusCodes.OK,
      "Pengajuan pembatalan berhasil dikirim dan menunggu persetujuan Admin",
      result,
    );
  };
  uploadBukti = async (
    req: TypedRequest<
      typeof cancelPenjualanSchema.body,
      any,
      typeof uploadBuktiPenjualanSchema.params
    >,
    res: Response,
  ): Promise => {
    const { id, type } = req.params;
    if (!["booking", "dp"].includes(type)) {
      sendResponse(res, StatusCodes.BAD_REQUEST, "Tipe upload tidak valid.");
      return;
    }
    if (!req.file?.buffer) {
      sendResponse(
        res,
        StatusCodes.BAD_REQUEST,
        "File dokumen wajib diunggah.",
      );
      return;
    }

    const result = await this.uploadBuktiUseCase.execute(
      id,
      type as "booking" | "dp",
      req.file.buffer,
    );
    sendResponse(
      res,
      StatusCodes.OK,
      `Bukti ${type} berhasil diunggah`,
      result,
    );
  };
  uploadSignature = async (
    req: TypedRequest<
      typeof uploadSignatureSchema.body,
      any,
      typeof uploadSignatureSchema.params
    >,
    res: Response,
  ): Promise => {
    const { id } = req.params;
    const { signatureBase64, nama, peran, tanggal } = req.body;

    const result = await this.saveSignatureUseCase.execute(
      id,
      signatureBase64,
      nama,
      peran,
      tanggal,
    );

    sendResponse(
      res,
      StatusCodes.OK,
      `Tanda tangan digital untuk ${peran} berhasil disimpan`,
      result,
    );
  };
  update = async (
    req: TypedRequest<
      typeof updatePenjualanSchema.body,
      any,
      typeof updatePenjualanSchema.params
    >,
    res: Response,
  ): Promise => {
    const { id } = req.params;
    const userId = req.user?.userId;

    const result = await this.updateUseCase.execute(
      id,
      req.body as Partial,
      userId,
    );

    sendResponse(
      res,
      StatusCodes.OK,
      "Data penjualan berhasil diperbarui dan direkam.",
      result,
    );
  };
  gantiKavling = async (
    req: TypedRequest<
      typeof gantiKavlingSchema.body,
      any,
      typeof gantiKavlingSchema.params
    >,
    res: Response,
  ): Promise => {
    const { id } = req.params;
    const { kavlingBaruId, alasan } = req.body;
    const userId = req.user!.userId;

    const result = await this.gantiKavlingUseCase.execute(
      id,
      kavlingBaruId,
      alasan,
      userId,
    );
    sendResponse(
      res,
      StatusCodes.OK,
      "Pengajuan ganti kavling berhasil dikirim dan menunggu persetujuan Admin.",
      result,
    );
  };
  getPengajuanBatal = async (req: Request, res: Response): Promise => {
    const status = req.query.status as
      | "PENDING"
      | "APPROVED"
      | "REJECTED"
      | undefined;
    const result = await this.getPengajuanBatalUseCase.execute(status);
    sendResponse(
      res,
      StatusCodes.OK,
      "Daftar pengajuan pembatalan berhasil diambil",
      result,
    );
  };

  getPengajuanGantiKavling = async (
    req: Request,
    res: Response,
  ): Promise => {
    const status = req.query.status as
      | "PENDING"
      | "APPROVED"
      | "REJECTED"
      | undefined;
    const result = await this.getPengajuanGantiKavlingUseCase.execute(status);
    sendResponse(
      res,
      StatusCodes.OK,
      "Daftar pengajuan ganti kavling berhasil diambil",
      result,
    );
  };

  approveBatal = async (
    req: TypedRequest<
      typeof approveSchema.body,
      any,
      typeof approveSchema.params
    >,
    res: Response,
  ): Promise => {
    const id = parseInt(req.params.id, 10);
    const { isApproved } = req.body;
    const userId = req.user!.userId;

    const result = await this.approveBatalUseCase.execute(
      id,
      userId,
      isApproved,
    );
    const msg = isApproved
      ? "Pembatalan berhasil disetujui dan dieksekusi"
      : "Pengajuan pembatalan ditolak";
    sendResponse(res, StatusCodes.OK, msg, result);
  };

  approveGantiKavling = async (
    req: TypedRequest<
      typeof approveSchema.body,
      any,
      typeof approveSchema.params
    >,
    res: Response,
  ): Promise => {
    const id = parseInt(req.params.id, 10);
    const { isApproved } = req.body;
    const userId = req.user!.userId;

    const result = await this.approveGantiKavlingUseCase.execute(
      id,
      userId,
      isApproved,
    );
    const msg = isApproved
      ? "Ganti Kavling berhasil disetujui dan dieksekusi"
      : "Pengajuan ganti kavling ditolak";
    sendResponse(res, StatusCodes.OK, msg, result);
  };
  regenerateSpr = async (
    req: TypedRequest<
      typeof approveSchema.body,
      any,
      typeof approveSchema.params
    >,
    res: Response,
  ): Promise => {
    const { id } = req.params;
    const result = await this.regenerateSprUseCase.execute(id);
    sendResponse(
      res,
      StatusCodes.OK,
      "Dokumen SPR berhasil di-generate ulang dengan aman.",
      result,
    );
  };
}

import { Prisma } from "@prisma/client";
import { type PrismaClient } from "@prisma/client";
import { NotFoundError } from "../../../domain/errors/NotFoundError.js";
import { ConflictError } from "../../../domain/errors/ConflictError.js";
import type { CreatePenjualanDTO } from "../../../domain/dtos/PenjualanDTO.js";
import type { CloudinaryService } from "../../../infrastructure/external/CloudinaryService.js";
import type { GenerateSprPdfUseCase } from "./GenerateSprPdfUseCase.js";

interface IBiayaTambahan {
  nama: string;
  nominal: number;
}

export class UpdatePenjualanUseCase {
  constructor(
    private readonly db: PrismaClient,
    private readonly cloudinaryService: CloudinaryService,
    private readonly generateSprPdfUseCase: GenerateSprPdfUseCase,
  ) {}

  async execute(
    noTransaksi: string,
    data: Partial,
    userId?: number,
  ) {
    const transactionResult = await this.db.$transaction(async (tx) => {
      const old = await tx.penjualan.findUnique({
        where: { noTransaksi },
        include: {
          customer: true,
          agent: true,
          kavling: { include: { perumahan: true } },
        },
      });

      if (!old) throw new NotFoundError("Data Penjualan tidak ditemukan");

      if (
        data.nama !== undefined ||
        data.noIdentitas !== undefined ||
        data.noTelepon !== undefined ||
        data.alamat !== undefined ||
        data.perusahaan !== undefined ||
        data.alamatKoresponden !== undefined
      ) {
        if (data.noIdentitas && data.noIdentitas !== old.customer.nikKtp) {
          const existingCustomer = await tx.customer.findUnique({
            where: { nikKtp: data.noIdentitas },
          });
          if (existingCustomer && existingCustomer.id !== old.customerId) {
            throw new ConflictError(
              `Gagal update! NIK KTP ${data.noIdentitas} sudah terdaftar untuk customer lain.`,
            );
          }
        }
        const updateCustomerData: Prisma.CustomerUpdateInput = {};
        if (data.nama !== undefined) updateCustomerData.nama = data.nama;
        if (data.noIdentitas !== undefined)
          updateCustomerData.nikKtp = data.noIdentitas;
        if (data.noTelepon !== undefined)
          updateCustomerData.noHp = data.noTelepon;
        if (data.alamat !== undefined)
          updateCustomerData.alamatKtp = data.alamat;
        if (data.perusahaan !== undefined)
          updateCustomerData.perusahaan = data.perusahaan ?? null;
        if (data.alamatKoresponden !== undefined)
          updateCustomerData.alamatKoresponden = data.alamatKoresponden ?? null;
        await tx.customer.update({
          where: { id: old.customerId },
          data: updateCustomerData,
        });
      }

      if (data.agent && old.agentId) {
        await tx.agent.update({
          where: { id: old.agentId },
          data: { nama: data.agent },
        });
      }

      const updateData: Prisma.PenjualanUpdateInput = {};
      let formattedPayment = data.caraPembayaran as string | undefined;
      if (formattedPayment) {
        formattedPayment = formattedPayment.toUpperCase().replace(/\s+/g, "_");
        updateData.caraPembayaran = formattedPayment as any;
      }

      if (data.keteranganAngsuran !== undefined) {
        updateData.keteranganAngsuran = data.keteranganAngsuran ?? null;
      }

      let overrideHargaDasarDariKavlingBaru: number | undefined = undefined;
      if (
        data.blok &&
        data.nomorUnit &&
        (data.blok !== old.kavling.blok ||
          data.nomorUnit !== old.kavling.nomorUnit)
      ) {
        const newKavling = await tx.kavling.findFirst({
          where: {
            perumahanId: old.kavling.perumahanId,
            blok: data.blok,
            nomorUnit: data.nomorUnit,
          },
        });
        if (newKavling && newKavling.id !== old.kavlingId) {
          if (newKavling.status !== "AVAILABLE") {
            throw new ConflictError(
              `Kavling Blok ${data.blok} No ${data.nomorUnit} tidak tersedia (Status: ${newKavling.status})`,
            );
          }
          await tx.kavling.update({
            where: { id: old.kavlingId },
            data: { status: "AVAILABLE" },
          });
          await tx.kavling.update({
            where: { id: newKavling.id },
            data: {
              status: old.kavling.status,
              namaTipe: data.tipe ?? newKavling.namaTipe,
              luasBangunan: data.luasBangunan ?? newKavling.luasBangunan,
              luasTanah: data.luasTanah ?? newKavling.luasTanah,
              hargaDasar: data.hargaDasar ?? newKavling.hargaDasar,
            },
          });
          updateData.kavling = { connect: { id: newKavling.id } };
          overrideHargaDasarDariKavlingBaru =
            data.hargaDasar ?? Number(newKavling.hargaDasar);
        }
      }

      if (data.hargaPromosi !== undefined)
        updateData.hargaPromosi = data.hargaPromosi ?? null;
      if (data.bank !== undefined) updateData.bank = data.bank ?? null;

      const currentCaraPembayaran = formattedPayment ?? old.caraPembayaran;
      const currentHargaDasar =
        overrideHargaDasarDariKavlingBaru ??
        data.hargaDasar ??
        Number(old.hargaDasar);
      const currentDiskon =
        data.diskonPenjualan ?? Number(old.diskonPenjualan ?? 0);
      const currentBookingFee = data.bookingFee ?? Number(old.bookingFee ?? 0);
      const plafonAwal =
        data.plafonAwal ??
        currentHargaDasar - currentDiskon - currentBookingFee;

      const existingTambahan = await tx.tagihan.findMany({
        where: {
          penjualanId: old.id,
          noTagihan: { startsWith: "INV-ADD-" },
        },
      });
      const totalTambahanLama = existingTambahan.reduce(
        (sum, t) => sum + Number(t.nominal),
        0,
      );

      const listBiayaTambahan = data.biayaTambahan as
        | IBiayaTambahan[]
        | undefined;
      const totalTambahanBaru = Array.isArray(listBiayaTambahan)
        ? listBiayaTambahan.reduce(
            (sum, b) => sum + (Number(b.nominal) || 0),
            0,
          )
        : 0;

      const totalSemuaBiayaTambahan = totalTambahanLama + totalTambahanBaru;

      const listTambahanKpr = data.biayaTambahanKpr as
        | IBiayaTambahan[]
        | undefined;
      const totalTambahanKpr = Array.isArray(listTambahanKpr)
        ? listTambahanKpr.reduce((sum, b) => sum + (Number(b.nominal) || 0), 0)
        : 0;

      let biayaKpr = 0;
      let plafonKredit = 0;
      let nilaiPengajuanKpr = 0;
      let dp = 0;
      let dpTidakDibayar = 0;
      let hargaJual = 0;

      if (
        currentCaraPembayaran === "CASH_KERAS" ||
        currentCaraPembayaran === "CASH_BERTAHAP"
      ) {
        hargaJual = data.hargaJual ?? currentHargaDasar - currentDiskon;
        if (currentCaraPembayaran === "CASH_BERTAHAP") {
          dp = data.dp ?? 0;
        }
      } else if (currentCaraPembayaran === "KPR") {
        biayaKpr = data.biayaKpr ?? plafonAwal * 0.06;
        plafonKredit = data.plafonKredit ?? plafonAwal + biayaKpr;
        const baseHargaJual = plafonKredit / 0.9;
        hargaJual =
          data.hargaJual ?? baseHargaJual + currentDiskon + totalTambahanKpr;
        nilaiPengajuanKpr =
          data.nilaiPengajuanKpr ??
          plafonKredit - totalSemuaBiayaTambahan + totalTambahanKpr;
        dpTidakDibayar =
          data.dpTidakDibayar ?? baseHargaJual * 0.1 - currentBookingFee;
        nilaiPengajuanKpr =
          data.nilaiPengajuanKpr ??
          plafonKredit - totalSemuaBiayaTambahan + totalTambahanKpr;
        dp = data.dp ?? dpTidakDibayar;
      }

      updateData.hargaDasar = currentHargaDasar;
      updateData.plafonAwal = plafonAwal;
      updateData.biayaKpr = biayaKpr > 0 ? biayaKpr : null;
      updateData.plafonKredit = plafonKredit > 0 ? plafonKredit : null;
      updateData.dpTidakDibayar = dpTidakDibayar > 0 ? dpTidakDibayar : null;
      updateData.nilaiPengajuanKpr =
        nilaiPengajuanKpr > 0 ? nilaiPengajuanKpr : null;
      updateData.dp = dp > 0 ? dp : null;
      updateData.hargaJual = hargaJual;

      if (data.biayaTambahanKpr !== undefined) {
        updateData.tambahanKpr = data.biayaTambahanKpr
          ? (data.biayaTambahanKpr as any)
          : Prisma.DbNull;
      }
      if (currentCaraPembayaran === "CASH_BERTAHAP" && data.termin) {
        updateData.termin = data.termin;
      } else {
        updateData.termin = null;
      }

      const updated = await tx.penjualan.update({
        where: { noTransaksi },
        data: updateData,
      });
      if (currentBookingFee > 0) {
        const existingBf = await tx.tagihan.findFirst({
          where: {
            penjualanId: old.id,
            pembayaran: { contains: "Booking" },
          },
        });

        if (!existingBf) {
          await tx.tagihan.create({
            data: {
              noTagihan: `INV-BF-${noTransaksi}`,
              customerId: old.customerId,
              penjualanId: old.id,
              pembayaran: "Booking Fee",
              nominal: currentBookingFee,
              jatuhTempo: new Date(old.tanggal),
              status: "BELUM_BAYAR",
            },
          });
        } else if (Number(existingBf.nominal) !== currentBookingFee) {
          await tx.tagihan.update({
            where: { id: existingBf.id },
            data: { nominal: currentBookingFee },
          });
        }
      }

      if (
        dp > 0 &&
        (currentCaraPembayaran === "KPR" ||
          currentCaraPembayaran === "CASH_BERTAHAP")
      ) {
        const existingDp = await tx.tagihan.findFirst({
          where: {
            penjualanId: old.id,
            pembayaran: { contains: "Down Payment" },
          },
        });
        if (!existingDp) {
          const dpDueDate = new Date(old.tanggal);
          dpDueDate.setDate(dpDueDate.getDate() + 14);
          await tx.tagihan.create({
            data: {
              noTagihan: `INV-DP-${noTransaksi}`,
              customerId: old.customerId,
              penjualanId: old.id,
              pembayaran: "Down Payment (DP)",
              nominal: dp,
              jatuhTempo: dpDueDate,
              status: "BELUM_BAYAR",
            },
          });
        } else if (Number(existingDp.nominal) !== dp) {
          await tx.tagihan.update({
            where: { id: existingDp.id },
            data: { nominal: dp },
          });
        }
      }

      if (
        currentCaraPembayaran === "CASH_BERTAHAP" &&
        data.termin &&
        data.termin > 0
      ) {
        const sisaPembayaran = Math.max(0, hargaJual - dp - currentBookingFee);
        const cicilanPerBulan = sisaPembayaran / data.termin;

        const existingCicilans = await tx.tagihan.findMany({
          where: {
            penjualanId: old.id,
            pembayaran: { startsWith: "Cicilan Ke-" },
          },
        });

        if (existingCicilans.length === 0 && sisaPembayaran > 0) {
          const baseDate = new Date(old.tanggal);

          for (let i = 1; i <= data.termin; i++) {
            const jatuhTempoCicilan = new Date(baseDate);

            jatuhTempoCicilan.setMonth(jatuhTempoCicilan.getMonth() + i);

            await tx.tagihan.create({
              data: {
                noTagihan: `INV-CCL-${noTransaksi}-${i}`,
                customerId: old.customerId,
                penjualanId: old.id,
                pembayaran: `Cicilan Ke-${i}`,
                nominal: cicilanPerBulan,
                jatuhTempo: jatuhTempoCicilan,
                status: "BELUM_BAYAR",
              },
            });
          }
        } else if (existingCicilans.length === data.termin) {
          for (const cicilan of existingCicilans) {
            if (Number(cicilan.nominal) !== cicilanPerBulan) {
              await tx.tagihan.update({
                where: { id: cicilan.id },
                data: { nominal: cicilanPerBulan },
              });
            }
          }
        }
      }

      if (Array.isArray(listBiayaTambahan) && listBiayaTambahan.length > 0) {
        const dueDate = new Date(old.tanggal);
        dueDate.setDate(dueDate.getDate() + 14);

        for (let i = 0; i < listBiayaTambahan.length; i++) {
          const biaya = listBiayaTambahan[i];
          if (typeof biaya !== "object" || biaya === null) continue;

          const namaBiaya = String(biaya.nama || "");
          const nominalBiaya = Number(biaya.nominal) || 0;

          if (!namaBiaya || nominalBiaya <= 0) continue;

          await tx.tagihan.create({
            data: {
              noTagihan: `INV-ADD-${noTransaksi}-${Date.now().toString().slice(-4)}-${i}-${Math.floor(Math.random() * 1000)}`,
              customerId: old.customerId,
              penjualanId: old.id,
              pembayaran: namaBiaya,
              nominal: nominalBiaya,
              jatuhTempo: dueDate,
              status: "BELUM_BAYAR",
            },
          });
        }
      }

      await tx.auditLog.create({
        data: {
          entityName: "Penjualan",
          entityId: noTransaksi,
          action: "UPDATE",
          changes: {
            before: old,
            after: updated,
            input_raw: data,
          } as unknown as Prisma.InputJsonValue,
          userId: userId ?? null,
        },
      });

      return updated;
    });

    const triggerUpdateSpr =
      (data.caraPembayaran !== undefined ||
        data.bank !== undefined ||
        (data.biayaTambahan && data.biayaTambahan.length > 0)) ??
      data.keteranganUpdateSpr !== undefined;

    if (transactionResult && triggerUpdateSpr) {
      try {
        if (transactionResult.fileSpr) {
          await this.db.riwayatSpr.create({
            data: {
              penjualanId: transactionResult.id,
              fileSpr: transactionResult.fileSpr,
              keterangan:
                data.keteranganUpdateSpr ??
                "Update Skema / Bank / Biaya Tambahan",
            },
          });
        }

        const pdfBuffer = await this.generateSprPdfUseCase.execute(
          transactionResult.id,
        );
        const sprUrl = await this.cloudinaryService.uploadFile(
          pdfBuffer,
          "bumantara/spr",
        );

        return await this.db.penjualan.update({
          where: { id: transactionResult.id },
          data: { fileSpr: sprUrl },
          include: {
            customer: true,
            kavling: { include: { perumahan: true, rekeningTujuan: true } },
            agent: true,
          },
        });
      } catch (error) {
        console.error(
          "Gagal auto-generate SPR setelah update skema atau bank:",
          error,
        );
      }
    }

    return transactionResult;
  }
}

import { Router } from "express";
import { checkHealth } from "../controllers/healthController.js";
import { createAuthRoutes } from "./authRoutes.js";
import { createUserRoutes } from "./userRoutes.js";
import { createOcrRoutes } from "./ocrRoutes.js";
import { createBankRekeningPtRoutes } from "./bankRekeningPtRoutes.js";
import { createCustomerRoutes } from "./customerRoutes.js";
import { container } from "../../infrastructure/di/container.js";
import { createPerumahanRoutes } from "./perumahanRoutes.js";
import { createDashboardRoutes } from "./dashboardRoutes.js";
import { createAgentRoutes } from "./agentRoutes.js";
import { createNotarisRoutes } from "./notarisRoutes.js";
import { createKavlingRoutes } from "./kavlingRoutes.js";
import { createCustomerKavlingRoutes } from "./customerKavlingRoutes.js";
import { createTagihanRoutes } from "./tagihanRoutes.js";
import { createPenjualanRoutes } from "./penjualanRoutes.js";
import { createFeeAgentRoutes } from "./feeAgentRoutes.js";
import { createVerifyRoutes } from "./verifyRoutes.js";
import { createAuditLogRoutes } from "./auditLogRoutes.js";
import { createProgressPenjualanRoutes } from "./progressPenjualanRoutes.js";
export const createMainRouter = (deps: typeof container): Router => {
  const router = Router();

  router.get("/health", checkHealth);
  router.use("/verify", createVerifyRoutes(deps.verifyController));

  router.use("/auth", createAuthRoutes(deps.authController));
  router.use("/users", createUserRoutes(deps.userController));
  router.use("/ocr", createOcrRoutes(deps.ocrController));

  router.use(
    "/bank-rekening",
    createBankRekeningPtRoutes(deps.bankRekeningPtController),
  );

  router.use("/customers", createCustomerRoutes(deps.customerController));
  router.use("/perumahan", createPerumahanRoutes(deps.perumahanController));
  router.use("/dashboard", createDashboardRoutes(deps.dashboardController));
  router.use("/agents", createAgentRoutes(deps.agentController));
  router.use("/notaris", createNotarisRoutes(deps.notarisController));
  router.use("/kavling", createKavlingRoutes(deps.kavlingController));
  router.use(
    "/customer-kavling",
    createCustomerKavlingRoutes(deps.customerKavlingController),
  );
  router.use("/tagihan", createTagihanRoutes(deps.tagihanController));
  router.use("/penjualan", createPenjualanRoutes(deps.penjualanController));
  router.use(
    "/progress-penjualan",
    createProgressPenjualanRoutes(deps.progressPenjualanController),
  );
  router.use("/fee-agents", createFeeAgentRoutes(deps.feeAgentController));
  router.use("/audit-logs", createAuditLogRoutes(deps.auditLogController));
  return router;
};

const router = createMainRouter(container);
export default router;

import PDFDocument from "pdfkit";
import type { Prisma } from "@prisma/client";
import { NotFoundError } from "../../../domain/errors/NotFoundError.js";
import type { IPenjualanRepository } from "../../../domain/repositories/IPenjualanRepo.js";
import QRCode from "qrcode";

export class GenerateSprPdfUseCase {
  constructor(private readonly penjualanRepo: IPenjualanRepository) {}

  async execute(penjualanId: number): Promise {
    const penjualan = await this.penjualanRepo.findById(penjualanId);

    if (!penjualan) {
      throw new NotFoundError("Data Penjualan tidak ditemukan");
    }

    const { customer, kavling, rekeningTujuan, tagihan } = penjualan;

    // --- 1. PRE-FETCH DATA TANDA TANGAN & LOGO (ASINKRON) ---
    const sigData = ["Pemesan", "Marketing", "Supervisor", "Manager"];
    const ttdData = penjualan.ttdData as Record<
      string,
      { nama: string; tanggal: string; url: string }
    > | null;
    const sigBuffers: Record = {};

    const verifyUrl = `http://localhost:5173/verify/${penjualan.noTransaksi}`;
    let qrCodeBuffer: Buffer | null = null;
    let logoBuffer: Buffer | null = null;

    // Ambil logo dari Cloudinary
    if (kavling.perumahan.logo) {
      try {
        const response = await fetch(kavling.perumahan.logo);
        const arrayBuffer = await response.arrayBuffer();
        logoBuffer = Buffer.from(arrayBuffer);
      } catch (err) {
        console.error("Gagal download logo perumahan", err);
      }
    }

    try {
      const qrDataUri = await QRCode.toDataURL(verifyUrl, {
        margin: 1,
        width: 80,
      });

      const base64Data = qrDataUri.split(",")[1];

      if (base64Data) {
        qrCodeBuffer = Buffer.from(base64Data, "base64");
      }
    } catch (err) {
      console.error("Gagal generate QR Code", err);
    }

    if (ttdData) {
      await Promise.all(
        sigData.map(async (role) => {
          if (ttdData[role]?.url) {
            try {
              const response = await fetch(ttdData[role].url);
              const arrayBuffer = await response.arrayBuffer();
              sigBuffers[role] = Buffer.from(arrayBuffer);
            } catch (e) {
              console.error(`Gagal download TTD ${role} dari Cloudinary`, e);
            }
          }
        }),
      );
    }

    // --- 2. PEMBUATAN DOKUMEN PDF (SINKRON) ---
    return new Promise((resolve, reject) => {
      try {
        const doc = new PDFDocument({ size: "A4", margin: 40 }); // Margin diperkecil
        const buffers: Buffer[] = [];

        doc.on("data", (buffer) => buffers.push(buffer));
        doc.on("end", () => resolve(Buffer.concat(buffers)));

        let y = 40;
        const startX = 40; // Margin kiri
        const contentWidth = 515; // Lebar konten dimaksimalkan
        const pageBottomLimit = 800;

        const checkY = (neededHeight: number) => {
          if (y + neededHeight > pageBottomLimit) {
            doc.addPage();
            y = 40;
          }
        };

        // --- HEADER LOGO ---
        checkY(80);
        if (logoBuffer) {
          // Hanya logo, hapus nama perumahan
          doc.image(logoBuffer, startX, y, { height: 50 });
        } else {
          doc
            .fontSize(16)
            .font("Helvetica-Bold")
            .fillColor("#0f172a")
            .text("BUMANTARA", startX, y);
        }

        y += 60; // Jarak setelah logo sangat ditekan

        // --- JUDUL DOKUMEN ---
        doc
          .fontSize(14)
          .fillColor("#000000")
          .font("Helvetica-Bold")
          .text("SURAT KONFIRMASI UNIT PEMESANAN", startX, y, {
            width: contentWidth,
            align: "center",
            underline: true,
          });
        y += 20;

        doc
          .fontSize(10)
          .font("Helvetica")
          .text("Yang bertanda tangan di bawah ini :", startX, y);
        y += 15;

        // Fungsi Helper untuk merender list data dengan jarak rapat
        const drawField = (label: string, value: string, extraMargin = 4) => {
          const labelWidth = 120;
          const textHeight =
            doc.heightOfString(value, {
              width: contentWidth - labelWidth - 10,
            }) || 12;
          checkY(textHeight + extraMargin);

          doc.font("Helvetica").text(label, startX, y);
          doc.text(":", startX + labelWidth, y);
          doc.font("Helvetica-Bold").text(value, startX + labelWidth + 10, y, {
            width: contentWidth - labelWidth - 10,
            lineBreak: true,
          });
          y += textHeight + extraMargin;
        };

        // --- CUSTOMER INFO ---
        let phoneStr = customer.noHp || "";
        if (phoneStr.startsWith("8")) {
          phoneStr = "0" + phoneStr;
        }

        // 2. Format Email (Sembunyikan jika kosong atau '-')
        const emailStr =
          customer.email && customer.email !== "-"
            ? `      Email: ${customer.email}`
            : "";

        // 3. Perbaiki NIK (Hilangkan prefix DUMMY- jika ada)
        let nikStr = customer.nikKtp || "";
        if (nikStr.startsWith("DUMMY-")) {
          nikStr = nikStr.replace("DUMMY-", "");
        }
        drawField("Nama", customer.nama);
        drawField("Alamat", customer.alamatKtp);
        drawField("No. Telepon / HP", `${phoneStr}${emailStr}`);

        // Render opsional jika data tersedia
        if (nikStr && nikStr !== "-") {
          drawField("No. Identitas", nikStr);
        }

        if (customer.perusahaan && customer.perusahaan !== "-") {
          drawField("Perusahaan", customer.perusahaan);
        }

        if (customer.alamatKoresponden && customer.alamatKoresponden !== "-") {
          // extraMargin dibesarkan sedikit khusus baris terakhir dari blok ini
          drawField("Alamat Korespondensi", customer.alamatKoresponden, 8);
        } else {
          y += 8; // Tetap berikan jarak jika field ini tidak dirender
        }
        checkY(15);
        doc
          .font("Helvetica")
          .text(
            "Telah menyetujui untuk memesan / membeli unit rumah dan atau kavling sebagai berikut:",
            startX,
            y,
          );
        y += 15;

        const formatRp = (num: number | Prisma.Decimal) => {
          const val =
            typeof num === "object" && "toNumber" in num
              ? num.toNumber()
              : Number(num);

          const roundedVal = Math.round(val);

          return `Rp. ${roundedVal.toLocaleString("id-ID")}`;
        };

        // --- UNIT INFO ---
        drawField("Perumahan", kavling.perumahan.nama);
        drawField(
          "Blok/Type",
          `Blok ${kavling.blok} No. ${kavling.nomorUnit} / ${kavling.namaTipe}`,
        );
        drawField("Harga Jual", formatRp(penjualan.hargaJual!));

        if (
          penjualan.diskonPenjualan &&
          Number(penjualan.diskonPenjualan) > 0
        ) {
          drawField("Diskon Penjualan", formatRp(penjualan.diskonPenjualan));
        }

        // --- UPDATE 1: Menampilkan Termin di Cara Pembayaran ---
        const caraBayarText = penjualan.caraPembayaran
          ? penjualan.caraPembayaran.replace(/_/g, " ")
          : "-";

        drawField("Cara Pembayaran", caraBayarText);

        if (penjualan.bank) {
          const bankLabel =
            penjualan.caraPembayaran === "KPR" ? "Bank KPR" : "Bank";
          drawField(bankLabel, penjualan.bank);
        }
        if (
          penjualan.nilaiPengajuanKpr &&
          Number(penjualan.nilaiPengajuanKpr) > 0
        ) {
          const labelPengajuan =
            penjualan.caraPembayaran === "KPR"
              ? "Nilai Pengajuan KPR"
              : "Nilai Pengajuan (Plafon)";

          drawField(labelPengajuan, formatRp(penjualan.nilaiPengajuanKpr), 10);
        }

        // --- TABEL PEMBAYARAN ---
        const colNo = startX;
        const colKet = startX + 30;
        const colTempo = startX + 240;
        const colNilai = startX + 370;
        const rowHeight = 18; // Row height dipadatkan

        checkY(rowHeight);
        doc
          .rect(startX, y, contentWidth, rowHeight)
          .fillAndStroke("#f0f0f0", "#000");
        doc.fillColor("#000").font("Helvetica-Bold").fontSize(9);
        doc.text("NO", colNo + 5, y + 5);
        doc.text("KETERANGAN", colKet + 5, y + 5);
        doc.text("JATUH TEMPO", colTempo + 5, y + 5);
        doc.text("NILAI", colNilai + 5, y + 5);
        y += rowHeight;

        let totalNilai = 0;
        doc.font("Helvetica").fontSize(9);

        const tagihanAwal =
          tagihan?.filter((t) => {
            const namaPembayaran = t.pembayaran.toLowerCase();
            return (
              namaPembayaran.includes("booking") ||
              namaPembayaran.includes("dp") ||
              namaPembayaran.includes("down")
            );
          }) || [];

        // Render tagihan
        if (tagihanAwal.length > 0) {
          tagihanAwal.forEach((p, idx) => {
            checkY(rowHeight);

            const dateStr = p.jatuhTempo
              .toLocaleDateString("id-ID", {
                day: "2-digit",
                month: "2-digit",
                year: "numeric",
              })
              .replace(/\//g, "-");

            doc.rect(startX, y, contentWidth, rowHeight).stroke();
            doc.text(`${idx + 1}.`, colNo + 5, y + 5);
            doc.text(p.pembayaran, colKet + 5, y + 5);
            doc.text(dateStr, colTempo + 5, y + 5);
            doc.text(formatRp(p.nominal), colNilai + 5, y + 5);

            // Garis vertikal pemisah kolom
            doc
              .moveTo(colKet, y)
              .lineTo(colKet, y + rowHeight)
              .stroke();
            doc
              .moveTo(colTempo, y)
              .lineTo(colTempo, y + rowHeight)
              .stroke();
            doc
              .moveTo(colNilai, y)
              .lineTo(colNilai, y + rowHeight)
              .stroke();

            totalNilai +=
              typeof p.nominal === "object" && "toNumber" in p.nominal
                ? p.nominal.toNumber()
                : Number(p.nominal);

            y += rowHeight;
          });
        }

        // Row Total
        checkY(rowHeight);
        doc.rect(startX, y, contentWidth, rowHeight).stroke();
        doc.font("Helvetica-Bold").text("JUMLAH", colKet + 5, y + 5);
        doc.text(formatRp(totalNilai), colNilai + 5, y + 5);
        doc
          .moveTo(colKet, y)
          .lineTo(colKet, y + rowHeight)
          .stroke();
        doc
          .moveTo(colNilai, y)
          .lineTo(colNilai, y + rowHeight)
          .stroke();

        // UBAH BAGIAN INI:
        y += rowHeight + 15; // Jarak setelah tabel: Tinggi baris + gap ekstra 15 poin

        const today = new Date()
          .toLocaleDateString("id-ID", {
            day: "2-digit",
            month: "2-digit",
            year: "numeric",
          })
          .replace(/\//g, "-");

        let extraGap = 15; // Jarak default jika tidak ada keterangan

        if (
          penjualan.caraPembayaran === "CASH_BERTAHAP" &&
          penjualan.keteranganAngsuran
        ) {
          const ketText = `Keterangan Angsuran: ${penjualan.keteranganAngsuran}`;
          doc.font("Helvetica-Bold").fontSize(9);

          // Hitung tinggi teks aktual berdasarkan batas lebarnya
          const textHeight = doc.heightOfString(ketText, {
            width: contentWidth / 2,
          });

          doc.text(ketText, startX, y, {
            width: contentWidth / 2,
            align: "left",
          });

          // Gap dinamis: tinggi teks + jarak ekstra 25 poin ke bawah agar lega
          extraGap = textHeight + 25;
        }

        doc
          .font("Helvetica")
          .fontSize(9)
          .text(`Dibuat Tanggal: ${today}`, startX, y, {
            width: contentWidth,
            align: "right",
          });

        y += extraGap; // Terapkan gap yang sudah dikalkulasi

        const w = contentWidth / 4;

        // Render Tanda Tangan & Nama
        sigData.forEach((title, i) => {
          const currentX = startX + w * i;

          doc
            .font("Helvetica")
            .fontSize(9)
            .text(title, currentX, y, { width: w, align: "center" });

          if (ttdData?.[title]) {
            const ttd = ttdData[title];

            // Cetak gambar TTD
            if (sigBuffers[title]) {
              try {
                // Diangkat ke y + 5 agar tidak membuang space kosong
                doc.image(sigBuffers[title], currentX + w / 2 - 25, y + 5, {
                  width: 50,
                  height: 30,
                });
              } catch (imgErr) {
                console.error(`Gagal render gambar PDF untuk ${title}`, imgErr);
              }
            }

            // Cetak Tanggal TTD ditarik ke atas
            if (ttd.tanggal) {
              const tglStr = new Date(ttd.tanggal).toLocaleDateString("id-ID", {
                day: "2-digit",
                month: "short",
                year: "numeric",
              });
              doc
                .fontSize(7)
                .font("Helvetica")
                .text(tglStr, currentX, y + 40, { width: w, align: "center" });
            }

            // Cetak Nama ditarik ke atas
            doc
              .fontSize(8)
              .font("Helvetica-Bold")
              .text(ttd.nama, currentX, y + 55, { width: w, align: "center" });

            doc.fontSize(9).font("Helvetica"); // Reset
          }
        });

        y += 50; // Jarak untuk menarik garis jauh lebih pendek
        const lineW = w - 20;

        // Render Garis TTD
        sigData.forEach((_, i) => {
          const cx = startX + w * i + w / 2;
          doc
            .moveTo(cx - lineW / 2, y)
            .lineTo(cx + lineW / 2, y)
            .stroke();
        });

        y += 20; // Jarak sebelum Terms dikurangi drastis

        // --- TERMS & BANK INFO ---
        checkY(70);
        doc.fontSize(8).font("Helvetica");
        const termLines = [
          "1. Harga jual pembelian unit rumah sudah termasuk biaya AJB, Sertipikat, IMB, Listrik, BPHTB, Biaya Proses KPR dan Notaris.",
          "2. Apabila terjadi pembatalan, uang tanda jadi (Booking Fee) tidak dapat dikembalikan / hangus.",
          "3. Surat konfirmasi ini sah apabila dilampirkan bukti transfer ke nomor rekening berikut:",
        ];

        termLines.forEach((text) => {
          doc.text(text, startX, y, { width: contentWidth, align: "justify" });
          y += 10; // Line height dipadatkan
        });

        y += 5;

        // Render Kotak Bank Rekening
        if (rekeningTujuan) {
          doc.rect(startX, y, 260, 40).stroke(); // Tinggi kotak diperkecil
          doc
            .font("Helvetica-Bold")
            .text(
              `Bank ${rekeningTujuan.namaBank} No Rekening : ${rekeningTujuan.noRekening}`,
              startX + 5,
              y + 8,
            );
          doc
            .font("Helvetica")
            .text(`a/n ${rekeningTujuan.atasNama}`, startX + 5, y + 22);
        }

        // Render QR Code
        if (qrCodeBuffer) {
          const qrX = startX + 360;
          const qrY = y - 10;

          // Gambar kotak pembungkus QR (Lebih kecil)
          doc.rect(qrX - 5, qrY - 5, 75, 85).stroke("#e2e8f0");

          // Masukkan gambar QR
          doc.image(qrCodeBuffer, qrX, qrY, { width: 65, height: 65 });

          // Tambahkan teks validasi di bawah QR
          doc.fontSize(6).font("Helvetica-Bold").fillColor("#64748b");
          doc.text("SCAN UNTUK VALIDASI", qrX - 5, qrY + 70, {
            width: 75,
            align: "center",
          });
        }

        doc.end();
      } catch (error) {
        reject(error instanceof Error ? error : new Error(String(error)));
      }
    });
  }
}

import type { Prisma } from "@prisma/client";
import type {
  CreatePenjualanDTO,
  PenjualanFilterDTO,
} from "../dtos/PenjualanDTO.js";
import type { OffsetPaginatedData } from "../../types/response.js";

export type PenjualanWithCompleteRelations = Prisma.PenjualanGetPayload<{
  include: {
    customer: true;
    kavling: {
      include: { perumahan: true; rekeningTujuan: true }; // <--- Menambahkan relasi rekeningTujuan di sini
    };
    rekeningTujuan: true;
    tagihan: true;
    agent: true;
  };
}>;

export type PenjualanWithRelations = Prisma.PenjualanGetPayload<{
  include: {
    customer: { select: { id: true; nama: true } };
    kavling: {
      select: {
        id: true;
        blok: true;
        nomorUnit: true;
        perumahan: { select: { nama: true } };
      };
    };
  };
}>;
export interface PenjualanPaginatedItem {
  id: string;
  dbId: number;
  noTransaksi: string;
  tanggal: string;
  nama: string;
  alamat: string;
  noTelepon: string;
  noIdentitas: string;
  perumahan: string;
  blok: string;
  alasanBatal: string | null;
  nomorUnit: string;
  tipe: string;
  luasBangunan: number;
  luasTanah: number;

  plafonAwal: number | null;
  biayaKpr?: number | null;
  plafonKredit?: number | null;
  dpTidakDibayar?: number | null;
  hargaJual: number | null;
  caraPembayaran: string | null;

  hargaDasar: number;
  dp: number;
  diskonPenjualan: number;
  hargaPromosi: number;
  bank: string;
  nilaiPengajuanKpr: number;
  bookingFee: number;
  status: string;
  agent: string;
  fileBuktiBooking: string;
  fileBuktiDp: string;
  fileSpr: string | null;
  ttdData?: any;
  tambahanKpr?: any;
  progressCicilan?: string;
  rekeningTujuanId?: number | null;
  rekeningTujuan?: {
    namaBank: string;
    noRekening: string;
    atasNama: string;
  } | null;
  riwayatGantiKavling?: any[];
  tagihan?: any[];
  progressPenjualan?: any;

  createdBy?: string;
  isPendingBatal?: boolean;
  createdAt?: string;
  updatedAt?: string;
}

export interface IPenjualanRepository {
  createWithTransaction(
    data: CreatePenjualanDTO,
  ): Promise;
  findWithOffsetPagination(
    page: number,
    limit: number,
    filters?: PenjualanFilterDTO & { status?: string },
  ): Promise<OffsetPaginatedData>;

  findById(id: number): Promise;
  update(
    id: number,
    data: Partial,
  ): Promise;
}

import { z } from "zod";
import { emptyAsUndefined } from "./emptySchema.js";
import type { PaymentMethod } from "@prisma/client";
import { PenjualanStatus } from "@prisma/client";
import { offsetPaginationQuerySchema } from "./paginationSchema.js";

export const createPenjualanSchema = {
  body: z.object({
    noIdentitas: z.string().min(16, "NIK minimal 16 karakter"),
    nama: z.string().min(3, "Nama minimal 3 karakter"),
    noTelepon: z.string().min(9, "No Telepon minimal 9 karakter"),
    alamat: z.string().min(5, "Alamat minimal 5 karakter"),
    perusahaan: emptyAsUndefined(z.string().optional()),
    alamatKoresponden: emptyAsUndefined(z.string().optional()),
    perumahan: z.string().min(1, "Perumahan wajib diisi"),
    blok: z.string().min(1, "Blok wajib diisi").max(10, "Blok Max 10 Karakter"),
    nomorUnit: z
      .string()
      .min(1, "Nomor unit wajib diisi")
      .max(10, "No Unit Max 10 Karakter"),
    tipe: z.string().min(1, "Tipe kavling wajib diisi"),
    luasBangunan: z.coerce.number().min(0),
    luasTanah: z.coerce.number().min(0),
    tanggal: z.string().datetime().or(z.string().min(1)),
    hargaDasar: z.coerce.number().min(1, "Harga dasar tidak valid"),
    hargaPromosi: emptyAsUndefined(z.coerce.number().min(0).optional()),
    diskonPenjualan: emptyAsUndefined(z.coerce.number().min(0).optional()),
    dp: emptyAsUndefined(z.coerce.number().min(0).optional()),
    bookingFee: emptyAsUndefined(z.coerce.number().min(0).optional()),
    bank: emptyAsUndefined(z.string().optional()),
    caraPembayaran: emptyAsUndefined(
      z
        .string()
        .transform((val) => {
          const formatted = val.toUpperCase().replace(/\s+/g, "_");
          if (["CASH_KERAS", "CASH_BERTAHAP", "KPR"].includes(formatted)) {
            return formatted as PaymentMethod;
          }
          throw new Error("Cara pembayaran tidak valid");
        })
        .optional(),
    ),
    nilaiPengajuanKpr: emptyAsUndefined(z.coerce.number().min(0).optional()),
    agent: z.string().min(1, "Agent wajib diisi"),
  }),
};
export const getPenjualanPaginatedSchema = {
  query: offsetPaginationQuerySchema.extend({
    status: emptyAsUndefined(z.nativeEnum(PenjualanStatus).optional()),
  }),
};
export const cancelPenjualanSchema = {
  params: z.object({
    id: z.string().min(1, "No Transaksi wajib diisi"),
  }),
  body: z.object({
    alasanBatal: z.string().min(5, "Alasan pembatalan minimal 5 karakter"),
  }),
};
export const uploadBuktiPenjualanSchema = {
  params: z.object({
    id: z.string().min(1, "No Transaksi wajib diisi"),
    type: z.string().min(1, "Type wajib diisi"),
  }),
  body: z.object({
    alasanBatal: z.string().min(5, "Alasan pembatalan minimal 5 karakter"),
  }),
};
export const uploadSignatureSchema = {
  params: z.object({
    id: z.string().min(1, "No Transaksi wajib diisi"),
  }),
  body: z.object({
    signatureBase64: z.string().min(1, "Data signature wajib diisi"),
    nama: z.string().min(1, "Nama wajib diisi"),
    peran: z.string().min(1, "Peran wajib diisi"),
    tanggal: z.string().min(1, "Tanggal wajib diisi"),
  }),
};
export const biayaTambahanSchema = z.object({
  nama: z.string().min(1, "Nama biaya wajib diisi"),
  nominal: z.coerce.number().min(0, "Nominal tidak boleh negatif"),
});
export const updatePenjualanSchema = {
  params: z.object({
    id: z.string().min(1, "No Transaksi wajib diisi"),
  }),
  body: z
    .object({
      nama: emptyAsUndefined(z.string().min(3).optional()),
      noIdentitas: emptyAsUndefined(z.string().min(16).optional()),
      noTelepon: emptyAsUndefined(z.string().optional()),
      alamat: emptyAsUndefined(z.string().optional()),
      perusahaan: emptyAsUndefined(z.string().optional()),
      alamatKoresponden: emptyAsUndefined(z.string().optional()),
      caraPembayaran: emptyAsUndefined(z.string().optional()),
      termin: emptyAsUndefined(z.coerce.number().int().min(1).optional()),
      bank: emptyAsUndefined(z.string().optional()),

      // TAMBAHAN: Diizinkan menerima input manual untuk kalkulasi
      plafonAwal: emptyAsUndefined(z.coerce.number().optional()),
      biayaKpr: emptyAsUndefined(z.coerce.number().optional()),
      nilaiPengajuanKpr: emptyAsUndefined(z.coerce.number().optional()),
      dp: emptyAsUndefined(z.coerce.number().optional()),
      bookingFee: emptyAsUndefined(z.coerce.number().optional()),
      diskonPenjualan: emptyAsUndefined(z.coerce.number().optional()),
      hargaPromosi: emptyAsUndefined(z.coerce.number().optional()),
      agent: emptyAsUndefined(z.string().optional()),
      blok: emptyAsUndefined(z.string().optional()),
      nomorUnit: emptyAsUndefined(z.string().optional()),
      tipe: emptyAsUndefined(z.string().optional()),
      luasBangunan: emptyAsUndefined(z.coerce.number().optional()),
      luasTanah: emptyAsUndefined(z.coerce.number().optional()),
      hargaJual: emptyAsUndefined(z.coerce.number().optional()),
      biayaTambahan: emptyAsUndefined(z.array(biayaTambahanSchema).optional()),
      biayaTambahanKpr: emptyAsUndefined(
        z.array(biayaTambahanSchema).optional(),
      ),
      keteranganUpdateSpr: emptyAsUndefined(z.string().optional()),
      keteranganAngsuran: emptyAsUndefined(z.string().optional()),
    })
    .partial(),
};

export const gantiKavlingSchema = {
  params: z.object({
    id: z.string().min(1, "No Transaksi wajib diisi"),
  }),
  body: z.object({
    kavlingBaruId: z.coerce.number().positive("Kavling baru wajib dipilih"),
    alasan: z.string().min(5, "Alasan ganti kavling minimal 5 karakter"),
  }),
};

export const approveSchema = {
  params: z.object({
    id: z.string().regex(/^\d+$/, "ID harus berupa angka"),
  }),
  body: z.object({
    isApproved: z.boolean({
      error: "Status persetujuan (isApproved) wajib diisi boolean",
    }),
  }),
};

generator client { provider = "prisma-client-js" }
datasource db { provider = "mysql" url = env("DATABASE_URL") }
enum Role { ADMIN @map("admin") MARKETING @map("marketing") CUSTOMER @map("customer") }
enum UnitStatus { AVAILABLE @map("Available") BOOKING @map("Booking") TERJUAL @map("Terjual") HOLD @map("Hold") } enum ActionType { CREATE UPDATE DELETE } enum PaymentStatus { BELUM_BAYAR @map("Belum Bayar") LUNAS @map("Lunas") }
enum PaymentMethod { CASH_KERAS @map("CASH KERAS") CASH_BERTAHAP @map("CASH BERTAHAP") KPR @map("KPR") }
enum ProgressStatus { MENUNGGU_VERIFIKASI @map("Menunggu Verifikasi") DISETUJUI @map("Disetujui") REVISI @map("Revisi") }
enum PenjualanStatus { BOOKED @map("Booked") PROSES @map("Proses") LUNAS @map("Lunas") BATAL @map("Batal") }
enum AgentStatus { AKTIF @map("Aktif") NONAKTIF @map("Nonaktif") }
enum SP3R { BANK @map("BANK") CASH @map("Cash") }
enum ApprovalStatus { PENDING APPROVED REJECTED }
model User { id Int @id @default(autoincrement()) username String @db.VarChar(100) email String @unique @db.VarChar(100) password String @db.VarChar(255) role Role createdAt DateTime @default(now()) @map("created_at") updatedAt DateTime @updatedAt @map("updated_at")
auditLogs AuditLog[] customers Customer[] pengajuanGantiKavling RiwayatGantiKavling[] @relation("PengajuGantiKavling") persetujuanGantiKavling RiwayatGantiKavling[] @relation("PenyetujuGantiKavling") pengajuanBatal PengajuanBatal[] @relation("PengajuBatal") persetujuanBatal PengajuanBatal[] @relation("PenyetujuBatal")
@@map("users") }
model Customer { id Int @id @default(autoincrement()) userId Int? @map("user_id") nikKtp String @unique @map("nik_ktp") @db.VarChar(20) nama String @db.VarChar(150) noHp String @map("no_hp") @db.VarChar(20) alamatKtp String @map("alamat_ktp") @db.Text alamatTinggal String? @map("alamat_tinggal") @db.Text email String? @db.VarChar(100) pekerjaan String? @db.VarChar(100) perusahaan String? @db.VarChar(150) bank String? @db.VarChar(100) alamatKoresponden String? @map("alamat_korespondensi") @db.Text fileKtp String? @map("file_ktp") @db.VarChar(255) fileKk String? @map("file_kk") @db.VarChar(255) fileNpwp String? @map("file_npwp") @db.VarChar(255) dokumenLainnya Json? @map("dokumen_lainnya") createdAt DateTime @default(now()) @map("created_at") updatedAt DateTime @updatedAt @map("updated_at")
user User? @relation(fields: [userId], references: [id]) penjualan Penjualan[] tagihan Tagihan[]
@@map("customers") }
model Perumahan { id Int @id @default(autoincrement()) nama String @unique @db.VarChar(150) logo String @unique @db.VarChar(150) alamat String @unique @db.VarChar(150) createdAt DateTime @default(now()) @map("created_at") updatedAt DateTime @updatedAt @map("updated_at")
kavlings Kavling[] bankRekeningPt BankRekeningPt[]
@@map("perumahan") }
model BankRekeningPt { id Int @id @default(autoincrement()) perumahanId Int @map("perumahan_id") namaBank String @map("nama_bank") @db.VarChar(100) noRekening String @map("no_rekening") @db.VarChar(50) atasNama String @map("atas_nama") @db.VarChar(150) createdAt DateTime @default(now()) @map("created_at")
perumahan Perumahan @relation(fields: [perumahanId], references: [id], onDelete: Restrict) penjualan Penjualan[] kavlings Kavling[]
@@map("bank_rekening_pt") }
model Notaris { id Int @id @default(autoincrement()) nama String @db.VarChar(150) biayaAjb Decimal @map("biaya_ajb") @db.Decimal(15, 2) createdAt DateTime @default(now()) @map("created_at") updatedAt DateTime @updatedAt @map("updated_at")
pics PicNotaris[] detailKavlingPajak DetailKavlingPajak[]
@@map("notaris") }
model PicNotaris { id Int @id @default(autoincrement()) notarisId Int @map("notaris_id") nama String @db.VarChar(150) noHp String @map("no_hp") @db.VarChar(20) alamat String? @db.Text createdAt DateTime @default(now()) @map("created_at") updatedAt DateTime @updatedAt @map("updated_at")
notaris Notaris @relation(fields: [notarisId], references: [id], onDelete: Cascade)
@@map("pic_notaris") }
model Agent { id Int @id @default(autoincrement()) nik String @unique @db.VarChar(20) kodeSales String? @unique @map("kode_sales") @db.VarChar(20) nama String @db.VarChar(150) alamat String? @db.Text noHp String @map("no_hp") @db.VarChar(20) email String? @db.VarChar(100) status AgentStatus @default(AKTIF) createdAt DateTime @default(now()) @map("created_at") updatedAt DateTime @updatedAt @map("updated_at")
pics PicAgent[] fees FeeAgent[] penjualan Penjualan[]
@@map("agents") }
model PicAgent { id Int @id @default(autoincrement()) agentId Int @map("agent_id") nama String @db.VarChar(150) noHp String @map("no_hp") @db.VarChar(20) alamat String? @db.Text createdAt DateTime @default(now()) @map("created_at") updatedAt DateTime @updatedAt @map("updated_at")
agent Agent @relation(fields: [agentId], references: [id], onDelete: Cascade)
@@map("pic_agents") }
model Kavling { id Int @id @default(autoincrement()) perumahanId Int @map("perumahan_id") blok String @db.VarChar(10) nomorUnit String @map("nomor_unit") @db.VarChar(10) namaTipe String @map("nama_tipe") @db.VarChar(50) luasBangunan Decimal @map("luas_bangunan") @db.Decimal(10, 2) luasTanah Decimal @map("luas_tanah") @db.Decimal(10, 2) hargaDasar Decimal @map("harga_dasar") @db.Decimal(15, 2) status UnitStatus @default(AVAILABLE) rekeningTujuanId Int? @map("rekening_tujuan_id") filePbg String? @map("file_pbg") @db.VarChar(255) fileSertifikatTanah String? @map("file_sertifikat_tanah") @db.VarChar(255) fileNopPbb String? @map("file_nop_pbb") @db.VarChar(255) createdAt DateTime @default(now()) @map("created_at") updatedAt DateTime @updatedAt @map("updated_at") riwayatLama RiwayatGantiKavling[] @relation("RiwayatKavlingLama") riwayatBaru RiwayatGantiKavling[] @relation("RiwayatKavlingBaru") perumahan Perumahan @relation(fields: [perumahanId], references: [id], onDelete: Restrict) rekeningTujuan BankRekeningPt? @relation(fields: [rekeningTujuanId], references: [id]) penjualan Penjualan[] progressProyek ProgressProyek[]
@@unique([perumahanId, blok, nomorUnit]) @@map("kavling") }
model Penjualan { id Int @id @default(autoincrement()) noTransaksi String @unique @map("no_transaksi") @db.VarChar(50) tanggal DateTime @db.Date customerId Int @map("customer_id") kavlingId Int @map("kavling_id") agentId Int? @map("agent_id") rekeningTujuanId Int? @map("rekening_tujuan_id") caraPembayaran PaymentMethod? @map("cara_pembayaran") termin Int? @map("termin") hargaDasar Decimal @map("harga_dasar") @db.Decimal(15, 2) plafonAwal Decimal? @map("plafon_awal") @db.Decimal(15, 2) biayaKpr Decimal? @map("biaya_kpr") @db.Decimal(15, 2) plafonKredit Decimal? @map("plafon_kredit") @db.Decimal(15, 2) dpTidakDibayar Decimal? @map("dp_tidak_dibayar") @db.Decimal(15, 2) hargaJual Decimal? @map("harga_jual") @db.Decimal(15, 2) dp Decimal? @db.Decimal(15, 2) diskonPenjualan Decimal? @map("diskon_penjualan") @db.Decimal(15, 2) hargaPromosi Decimal? @map("harga_promosi") @db.Decimal(15, 2) bank String? @db.VarChar(100) nilaiPengajuanKpr Decimal? @map("nilai_pengajuan_kpr") @db.Decimal(15, 2) bookingFee Decimal? @map("booking_fee") @db.Decimal(15, 2) status PenjualanStatus @default(BOOKED) alasanBatal String? @map("alasan_batal") @db.Text keteranganAngsuran String? @map("keterangan_angsuran") @db.Text fileSpr String? @map("file_spr") @db.VarChar(255) fileBuktiBooking String? @map("file_bukti_booking") @db.VarChar(255) fileBuktiDp String? @map("file_bukti_dp") @db.VarChar(255) ttdData Json? @map("ttd_data") tambahanKpr Json? @map("tambahan_kpr") createdBy String? @map("created_by") @db.VarChar(100) createdAt DateTime @default(now()) @map("created_at") updatedAt DateTime @updatedAt @map("updated_at") riwayatGantiKavling RiwayatGantiKavling[] customer Customer @relation(fields: [customerId], references: [id]) kavling Kavling @relation(fields: [kavlingId], references: [id]) agent Agent? @relation(fields: [agentId], references: [id]) rekeningTujuan BankRekeningPt? @relation(fields: [rekeningTujuanId], references: [id]) tagihan Tagihan[] detailKavlingPajak DetailKavlingPajak? feeAgent FeeAgent? progressPenjualan ProgressPenjualan? pengajuanBatal PengajuanBatal[] riwayatSpr RiwayatSpr[]
@@map("penjualan") }
model DetailKavlingPajak { id Int @id @default(autoincrement()) penjualanId Int @unique @map("penjualan_id") notarisId Int? @map("notaris_id") lantai String? @db.VarChar(10) luasBangunan String? @map("luas_bangunan") @db.VarChar(20) lokasiStrategis String? @map("lokasi_strategis") @db.VarChar(50) tanggalAkadPpjb DateTime? @map("tanggal_akad_ppjb") @db.Date akadPpjb String? @map("akad_ppjb") @db.VarChar(100) tanggalAkadAjbPpat DateTime? @map("tanggal_akad_ajb_ppat") @db.Date tanggalPembayaranPph DateTime? @map("tanggal_pembayaran_pph") @db.Date tanggalPembayaranBphtb DateTime? @map("tanggal_pembayaran_bphtb") @db.Date pembiayaan String? @db.VarChar(100) sp3r SP3R? @default(BANK) lebihTanah Decimal? @map("lebih_tanah") @db.Decimal(15, 2) biayaStrategis Decimal? @map("biaya_strategis") @db.Decimal(15, 2) nrBiayaKprAsuransi Decimal? @map("nr_biaya_kpr_asuransi") @db.Decimal(15, 2) nrDiskonAngsuran Decimal? @map("nr_diskon_angsuran") @db.Decimal(15, 2) nrDiskonCash Decimal? @map("nr_diskon_cash") @db.Decimal(15, 2) nrBiayaBbn Decimal? @map("nr_biaya_bbn") @db.Decimal(15, 2) nrBiayaNotarisAjb Decimal? @map("nr_biaya_notaris_ajb") @db.Decimal(15, 2) nrBiayaAppraisal Decimal? @map("nr_biaya_appraisal") @db.Decimal(15, 2) nrBiayaBphtb Decimal? @map("nr_biaya_bphtb") @db.Decimal(15, 2) nrLainLain Decimal? @map("nr_lain_lain") @db.Decimal(15, 2) nrTotalSubsidi Decimal? @map("nr_total_subsidi") @db.Decimal(15, 2) nrNilaiPenyerahan Decimal? @map("nr_nilai_penyerahan") @db.Decimal(15, 2) nrPpn Decimal? @map("nr_ppn") @db.Decimal(15, 2) nrBphtb Decimal? @map("nr_bphtb") @db.Decimal(15, 2) nrPph Decimal? @map("nr_pph") @db.Decimal(15, 2) pjBiayaKpr Decimal? @map("pj_biaya_kpr") @db.Decimal(15, 2) pjBiayaAsuransi Decimal? @map("pj_biaya_asuransi") @db.Decimal(15, 2) pjDiskonAngsuran Decimal? @map("pj_diskon_angsuran") @db.Decimal(15, 2) pjBiayaBbn Decimal? @map("pj_biaya_bbn") @db.Decimal(15, 2) pjBiayaAjb Decimal? @map("pj_biaya_ajb") @db.Decimal(15, 2) pjBiayaAppraisal Decimal? @map("pj_biaya_appraisal") @db.Decimal(15, 2) pjBphtb Decimal? @map("pj_bphtb") @db.Decimal(15, 2) pjLainLain Decimal? @map("pj_lain_lain") @db.Decimal(15, 2) pjTotalSubsidi Decimal? @map("pj_total_subsidi") @db.Decimal(15, 2) pjNilaiPenyerahan Decimal? @map("pj_nilai_penyerahan") @db.Decimal(15, 2) pjPpn Decimal? @map("pj_ppn") @db.Decimal(15, 2) pjBphtbPajak Decimal? @map("pj_bphtb_pajak") @db.Decimal(15, 2) pjPph Decimal? @map("pj_pph") @db.Decimal(15, 2) pjTotalBphtbPph Decimal? @map("pj_total_bphtb_pph") @db.Decimal(15, 2) ajbNjopTanahPerMeter Decimal? @map("ajb_njop_tanah_per_meter") @db.Decimal(15, 2) ajbNjopTanah Decimal? @map("ajb_njop_tanah") @db.Decimal(15, 2) ajbNjopBangunanPerMeter Decimal? @map("ajb_njop_bangunan_per_meter") @db.Decimal(15, 2) ajbNjopBangunan Decimal? @map("ajb_njop_bangunan") @db.Decimal(15, 2) ajbNjopTotal Decimal? @map("ajb_njop_total") @db.Decimal(15, 2) ajbPpn Decimal? @map("ajb_ppn") @db.Decimal(15, 2) ajbBphtb Decimal? @map("ajb_bphtb") @db.Decimal(15, 2) ajbPph Decimal? @map("ajb_pph") @db.Decimal(15, 2) ajbTotalBphtbPph Decimal? @map("ajb_total_bphtb_pph") @db.Decimal(15, 2) ajbSelisihPajakPbb Decimal? @map("ajb_selisih_pajak_pbb") @db.Decimal(15, 2) ajbUping Decimal? @map("ajb_uping") @db.Decimal(15, 2)
penjualan Penjualan @relation(fields: [penjualanId], references: [id], onDelete: Cascade) notaris Notaris? @relation(fields: [notarisId], references: [id], onDelete: SetNull)
@@map("detail_kavling_pajak") }
model Tagihan { id Int @id @default(autoincrement()) noTagihan String @unique @map("no_tagihan") @db.VarChar(50) customerId Int @map("customer_id") penjualanId Int @map("penjualan_id") pembayaran String @db.VarChar(255) nominal Decimal @db.Decimal(15, 2) jatuhTempo DateTime @map("jatuh_tempo") @db.Date status PaymentStatus @default(BELUM_BAYAR) fileBukti String? @map("file_bukti") @db.VarChar(255) reminderBerikutnya DateTime? @map("reminder_berikutnya") @db.Date isRefunded Boolean @default(false) @map("is_refunded") fileBuktiRefund String? @map("file_bukti_refund") @db.VarChar(255) ttdData Json? @map("ttd_data")
createdAt DateTime @default(now()) @map("created_at") updatedAt DateTime @updatedAt @map("updated_at")
customer Customer @relation(fields: [customerId], references: [id]) penjualan Penjualan @relation(fields: [penjualanId], references: [id])
