model FeeAgent { id Int @id @default(autoincrement()) agentId Int @map("agent_id") penjualanId Int @unique @map("penjualan_id") bookingNominal Decimal? @map("booking_nominal") @db.Decimal(15, 2) bookingTanggal DateTime? @map("booking_tanggal") @db.Date bookingBukti String? @map("booking_bukti") @db.VarChar(255) closingNominal Decimal? @map("closing_nominal") @db.Decimal(15, 2) closingTanggal DateTime? @map("closing_tanggal") @db.Date closingBukti String? @map("closing_bukti") @db.VarChar(255) marketingNominal Decimal? @map("marketing_nominal") @db.Decimal(15, 2) marketingTanggal DateTime? @map("marketing_tanggal") @db.Date marketingBukti String? @map("marketing_bukti") @db.VarChar(255) createdAt DateTime @default(now()) @map("created_at") updatedAt DateTime @updatedAt @map("updated_at")
