@@map("fee_agent") }
model Spk { id Int @id @default(autoincrement()) noSpk String @unique @map("no_spk") @db.VarChar(100) tanggalSpk DateTime @map("tanggal_spk") @db.Date judulPekerjaan String @map("judul_pekerjaan") @db.VarChar(255) lokasi String @db.Text jangkaWaktu Int @map("jangka_waktu") nilaiKontrak Decimal @map("nilai_kontrak") @db.Decimal(15, 2) namaPihakPertama String @map("nama_pihak_pertama") @db.VarChar(150) nikPihakPertama String @map("nik_pihak_pertama") @db.VarChar(20) namaPihakKedua String @map("nama_pihak_kedua") @db.VarChar(150) nikPihakKedua String @map("nik_pihak_kedua") @db.VarChar(20) alamatPihakKedua String @map("alamat_pihak_kedua") @db.Text namaBank String @map("nama_bank") @db.VarChar(100) noRekening String @map("no_rekening") @db.VarChar(50) atasNamaRekening String @map("atas_nama_rekening") @db.VarChar(150) fileSpk String? @map("file_spk") @db.VarChar(255) createdAt DateTime @default(now()) @map("created_at") updatedAt DateTime @updatedAt @map("updated_at")
@@map("spk") }
model ProgressProyek { id Int @id @default(autoincrement()) kavlingId Int @map("kavling_id") pelaksana String @db.VarChar(150) tanggalLaporan DateTime @map("tanggal_laporan") @db.Date tahapanPekerjaan String @map("tahapan_pekerjaan") @db.VarChar(150) persentase Int @default(0) keterangan String @db.Text kendala String? @db.Text fotoLapangan Json? @map("foto_lapangan") status ProgressStatus @default(MENUNGGU_VERIFIKASI) createdAt DateTime @default(now()) @map("created_at") updatedAt DateTime @updatedAt @map("updated_at")
kavling Kavling @relation(fields: [kavlingId], references: [id])
@@map("progress_proyek") } model AuditLog { id Int @id @default(autoincrement()) entityName String @map("entity_name") @db.VarChar(100) entityId String @map("entity_id") @db.VarChar(50) action ActionType changes Json userId Int? @map("user_id") createdAt DateTime @default(now()) @map("created_at")
user User? @relation(fields: [userId], references: [id], onDelete: SetNull)
@@map("audit_logs") }
model RiwayatGantiKavling { id Int @id @default(autoincrement()) penjualanId Int @map("penjualan_id") kavlingLamaId Int @map("kavling_lama_id") kavlingBaruId Int @map("kavling_baru_id") alasan String? @db.Text
status ApprovalStatus @default(PENDING) requestedById Int? @map("requested_by_id") approvedById Int? @map("approved_by_id")
createdAt DateTime @default(now()) @map("created_at") updatedAt DateTime @default(now()) @updatedAt @map("updated_at")
penjualan Penjualan @relation(fields: [penjualanId], references: [id], onDelete: Cascade) kavlingLama Kavling @relation("RiwayatKavlingLama", fields: [kavlingLamaId], references: [id], onDelete: Restrict) kavlingBaru Kavling @relation("RiwayatKavlingBaru", fields: [kavlingBaruId], references: [id], onDelete: Restrict)
requestedBy User? @relation("PengajuGantiKavling", fields: [requestedById], references: [id], onDelete: SetNull) approvedBy User? @relation("PenyetujuGantiKavling", fields: [approvedById], references: [id], onDelete: SetNull)
@@map("riwayat_ganti_kavling") }
model PengajuanBatal { id Int @id @default(autoincrement()) penjualanId Int @map("penjualan_id") alasan String @db.Text status ApprovalStatus @default(PENDING) requestedById Int? @map("requested_by_id") approvedById Int? @map("approved_by_id") createdAt DateTime @default(now()) @map("created_at") updatedAt DateTime @updatedAt @map("updated_at")
penjualan Penjualan @relation(fields: [penjualanId], references: [id], onDelete: Cascade) requestedBy User? @relation("PengajuBatal", fields: [requestedById], references: [id], onDelete: SetNull) approvedBy User? @relation("PenyetujuBatal", fields: [approvedById], references: [id], onDelete: SetNull)
@@map("pengajuan_batal") }
model RiwayatSpr { id Int @id @default(autoincrement()) penjualanId Int @map("penjualan_id") fileSpr String @map("file_spr") @db.VarChar(255) keterangan String? @db.VarChar(255) createdAt DateTime @default(now()) @map("created_at")
penjualan Penjualan @relation(fields: [penjualanId], references: [id], onDelete: Cascade)
@@map("riwayat_spr") }
model ProgressPenjualan { id Int @id @default(autoincrement()) penjualanId Int @unique @map("penjualan_id")
// Tahap KPR berkasCustomerValid Boolean @default(false) @map("berkas_customer_valid") fileSp3k String? @map("file_sp3k") @db.VarChar(255) fileSalinanAjb String? @map("file_salinan_ajb") @db.VarChar(255)
// Tahap Cash Bertahap filePpjb String? @map("file_ppjb") @db.VarChar(255)
// Umum (Semua Skema) nilaiAjb Decimal? @map("nilai_ajb") @db.Decimal(15, 2) biayaBphtb Decimal? @map("biaya_bphtb") @db.Decimal(15, 2) biayaPph Decimal? @map("biaya_pph") @db.Decimal(15, 2) fileAjb String? @map("file_ajb") @db.VarChar(255) fileBast String? @map("file_bast") @db.VarChar(255) checklistBast Json? @map("checklist_bast") // Menyimpan key dynamic & value dynamic
createdAt DateTime @default(now()) @map("created_at") updatedAt DateTime @updatedAt @map("updated_at")
penjualan Penjualan @relation(fields: [penjualanId], references: [id], onDelete: Cascade)
@@map("progress_penjualan") }

